body.script:
//
					const slides = document.querySelectorAll('.slide');
					const ind = document.getElementById('ind');
					let cur = 0;

					function show(i) {
						slides[cur].classList.remove('active');
						cur = ((i % slides.length) + slides.length) % slides.length;
						const slide = slides[cur];
						const iframe = slide.querySelector('iframe');
						if (!iframe.dataset.loaded) {
							iframe.src = slide.dataset.src;
							iframe.dataset.loaded = '1';
						}
						slide.classList.add('active');
						ind.textContent = slide.dataset.label;
					}

					show(0);

					document.addEventListener('keydown', e => {
						if (e.key === 'ArrowRight') show(cur + 1);
						else if (e.key === 'ArrowLeft') show(cur - 1);
					});

					let touchX = null;
					const overlay = document.getElementById('swipe-overlay');
					overlay.addEventListener('touchstart', e => {
						touchX = e.touches[0].clientX;
					}, { passive: true });
					overlay.addEventListener('touchend', e => {
						if (touchX === null) return;
						const dx = e.changedTouches[0].clientX - touchX;
						touchX = null;
						if (Math.abs(dx) < 40) return;
						show(dx < 0 ? cur + 1 : cur - 1);
					}, { passive: true });
				//

//
					const cfg              = document.getElementById('cfg').dataset;
					const INSTRUMENT       = cfg.instrument;
					const ASSET            = cfg.asset;
					// Candles are Binance spot (see dankbit.trade.get_candles) —
					// BTC/ETH are the only assets this addon ever serves a chart
					// for, so this string concat mirrors the server-side
					// _BINANCE_SYMBOL_MAP without needing a new cfg field.
					document.getElementById('exchange-label').textContent = 'Binance Spot · ' + ASSET + 'USDT';
					const MONTHLY_INST     = cfg.monthly || '';
					const REFRESH          = parseInt(cfg.refresh, 10) * 1000;
					// Also drives Bands' own poll interval (see setInterval(refreshBands, ...)
					// below) — not just the Zones boxes despite the name/setting.
					const ZONES_BOX_REFRESH = parseInt(cfg.zonesBoxRefresh, 10) * 1000;
					const ZONES_BOX_WINDOW_HOURS = parseInt(cfg.zonesBoxWindowHours, 10);
					// Always "false" now — /oi/<asset> (its own "Top OI(s)"
					// checkbox) has been removed; kept as an explicit context
					// key/flag since MINIMAL_CHART below still reads it.
					const SHOW_GAMMA_POINT = cfg.showGammaPoint === 'true';
					// Always "false" now — /mp/<instrument> (its own "Strike
					// Gamma" indicator) has been removed; kept as an explicit
					// context key/flag since MINIMAL_CHART below still reads it.
					const SHOW_STRIKE_GAMMA = cfg.showStrikeGamma === 'true';
					// Thales Forecast candle colors — user-configurable via
					// Settings → Dankbit → Thales Forecast (res.config.settings),
					// defaults are light red/green so forecast candles stay
					// easily distinguishable from the real teal/red candle series.
					const FORECAST_UP_COLOR = cfg.forecastUpColor || '#a5d6a7';
					const FORECAST_DOWN_COLOR = cfg.forecastDownColor || '#ef9a9a';
					const FORECAST_WICK_UP_COLOR = cfg.forecastWickUpColor || '#66bb6a';
					const FORECAST_WICK_DOWN_COLOR = cfg.forecastWickDownColor || '#e57373';
					// /oi/<asset> and /mp/<instrument> are the minimal pages
					// (candles + exactly one gamma indicator each — no
					// Gamma Horizon, zones, bands and Thales Forecast overlays
					// are not rendered on the two minimal chart pages
					// checkboxes); the footer (trade count/nearest expiry) is
					// untouched either way.
					const MINIMAL_CHART = SHOW_GAMMA_POINT || SHOW_STRIKE_GAMMA;
					// Gamma Horizon is a display-only term-Gamma overlay. It owns
					// no backend dependency from Forecast/Bands/Greeks/Robot and is
					// deliberately off by default.
					let SHOW_GAMMA_HORIZON = false;
					// User-toggleable via the "Zones" checkbox (Delta Chart only)
					// — controls the yellow top/bottom
					// zero-crossing boxes (High Zone/Low Zone) and the teal Seller
					// Max Profit/Buyer Max Loss box (Middle Zone), i.e. everything
					// refreshZonesBoxes()/clearZonesBoxes() draw. Checked/on by
					// default (matching the checkbox's own default-checked state
					// above), since these boxes were always-on before this flag
					// existed — unchecking it stops refreshZonesBoxes() from
					// calling the server at all, purely to reduce server load.
					// This has no effect on dankbit.bands either way: get_box()
					// (which /api/zones-box/<asset> calls) never persists,
					// checked or not — only the 4-hourly compute_snapshot() cron
					// ever writes to that model.
					let SHOW_ZONES_BOXES = true;
					// User-toggleable via the "Bands" checkbox. Bands are the pure
					// Thales upper/lower Longs-vs-Shorts curve intersections
					// (high_resistance/low_support), not Smart Liquidity and not an
					// average/blend with Smart Liquidity.
					let SHOW_BANDS = false;
					// Smart Liquidity is kept as a separate optional layer. It can still
					// feed forecast logic on the backend, but it no longer replaces,
					// averages, or compresses the displayed Green/Red Bands.
					const SMART_LIQ_VISIBILITY_STORAGE_KEY = 'dankbit_show_smart_liquidity';
					let SHOW_SMART_LIQUIDITY = localStorage.getItem(SMART_LIQ_VISIBILITY_STORAGE_KEY) === 'true';
					const smartLiquidityToggle = document.getElementById('smart-liquidity-toggle');
					if (smartLiquidityToggle) smartLiquidityToggle.checked = SHOW_SMART_LIQUIDITY;
					// Trade window used by the yellow/teal zones boxes (Delta Chart
					// only, "Zones from" dropdown next to "Bands") — 'midnight' is the
					// original since-00:00-UTC-through-now default; '2'/'4' select
					// fixed trailing windows, while 'configured' uses
					// ZONES_BOX_WINDOW_HOURS (see dankbit.zones_box_window_hours).
					// 'auto' is a zones-boxes-only mode — it sends ?hours=auto and
					// lets the server size the trailing window off the nearest
					// expiry's own time-to-settlement (see _auto_window_hours /
					// zones_box_json), the same behaviour /4l/<asset>'s own "Auto"
					// window has; every other Option Flow consumer (Bands, Smart
					// Liquidity, Forecast) treats 'auto' exactly like the default
					// 00:00-UTC view (selectedOptionFlowHours() returns null for it).
					// Only a trailing-window selection is ever
					// sent as a query param (see refreshZonesBoxes()) — a live,
					// non-persisted override on the server side (see get_box()'s
					// hours param); the 4-hourly compute_snapshot() cron and every
					// other viewer's default midnight-based view are completely
					// unaffected either way.
					let ZONES_BOX_WINDOW_MODE = 'midnight';
					function selectedOptionFlowHours() {
						if (ZONES_BOX_WINDOW_MODE === 'midnight' || ZONES_BOX_WINDOW_MODE === 'auto') return null;
						return ZONES_BOX_WINDOW_MODE === 'configured'
							? ZONES_BOX_WINDOW_HOURS
							: parseInt(ZONES_BOX_WINDOW_MODE, 10);
					}
					function withOptionFlowWindow(url) {
						const hours = selectedOptionFlowHours();
						if (hours === null) return url;
						return url + (url.includes('?') ? '&' : '?') + 'hours=' + hours;
					}
					// "Light"/"Dark" theme dropdown (all 3 TV chart pages — Delta
					// Chart, Gamma Chart, Strike Gamma) — see onThemeChange()/
					// applyTheme() further down. Light is the default, matching
					// this chart's original all-white look, unless the browser
					// already has a saved preference (THEME_STORAGE_KEY, a plain
					// localStorage entry — per-browser, not per-account, since
					// there's no user-settings model this addon writes to for
					// display prefs) from a previous visit, in which case that
					// preference is honored immediately (see the createChart call
					// and the select-sync block below) rather than flashing light
					// mode first. A few indicators draw their own line stroke
					// using a fixed black/gray color that would otherwise blend
					// into a black chart background — axisBlack()/rulerColor()
					// swap those to a light gray whenever dark mode is active,
					// used in place of the literal 'black'/'#555' in
					// drawGammaTopLine(), the delta=0 "supply" line color, and
					// the ruler lines.
					const THEME_STORAGE_KEY = 'dankbit_theme';
					let DARK_MODE = localStorage.getItem(THEME_STORAGE_KEY) === 'dark';
					function axisBlack() { return DARK_MODE ? '#e8e8e8' : '#000000'; }
					function rulerColor() { return DARK_MODE ? '#aaaaaa' : '#555555'; }
					// Sync the theme <select> and the body.dark CSS class to
					// whatever DARK_MODE resolved to above — the markup always
					// defaults to the "light" option server-side (there being no
					// per-user server-side setting to render it from), so a
					// returning visitor with a saved "dark" preference needs this
					// corrected client-side before anything is drawn.
					document.getElementById('theme-select').value = DARK_MODE ? 'dark' : 'light';
					document.body.classList.toggle('dark', DARK_MODE);

					// "Settings" button/dialog (all 3 TV chart pages, after Ruler) —
					// user-pickable colors for the Zones boxes and Bands lines,
					// persisted per-browser via localStorage (same pattern as
					// THEME_STORAGE_KEY above), not a server-side setting. Applies
					// on every page even though Zones/Bands only ever draw data on
					// the Delta Chart (MINIMAL_CHART suppresses them elsewhere) —
					// harmless no-op there since the series just never get data.
					const COLOR_STORAGE_KEY = 'dankbit_chart_colors';
					const LINE_STYLE_STORAGE_KEY = 'dankbit_chart_line_styles';
					const FORECAST_COUNT_STORAGE_KEY = 'dankbit_forecast_candle_counts';
					const BAND_SMOOTHING_STORAGE_KEY = 'dankbit_band_adaptive_smoothing';
					const BAND_SMOOTHING_STATE_KEY = 'dankbit_band_smoothing_state_' + ASSET;
					const GAMMA_HORIZON_SETTINGS_KEY = 'dankbit_gamma_horizon_settings';
					const GREEKS_HORIZON_SNAPSHOT_KEY = 'dankbit_greeks_horizon_snapshots_' + ASSET;
					const FORECAST_MAX_COUNTS = { '1h': 72, '4h': 18, '1d': 3 };
					const DEFAULT_COLORS = {
						zonesBox: '#fbc02d',
						middleZone: '#008080',
						bandUpper: '#2e7d32',
						bandLower: '#c62828',
						smartLiqUpper: '#2e7d32',
						smartLiqLower: '#c62828',
						gammaBand: '#c9a0dc',
						forecastUp: FORECAST_UP_COLOR,
						forecastDown: FORECAST_DOWN_COLOR,
						forecastWickUp: FORECAST_WICK_UP_COLOR,
						forecastWickDown: FORECAST_WICK_DOWN_COLOR,
					};
					const DEFAULT_LINE_STYLES = {
						bandUpper: 'solid',
						bandLower: 'solid',
						gammaBand: 'dashed',
						smartLiqUpper: 'dashed',
						smartLiqLower: 'dashed',
					};
					const DEFAULT_GAMMA_HORIZON_SETTINGS = {
						D1: { visible:true, color:'#ff9800', style:'dashed', width:1 },
						W:  { visible:true, color:'#7e57c2', style:'solid', width:1 },
						M:  { visible:true, color:'#00acc1', style:'dashed', width:1 },
						YE: { visible:true, color:'#d81b60', style:'solid', width:2 },
						weeklyCount:3,
						monthlyCount:3,
						showLabels:true,
						showGreeks:true,
						recent:{color:'#ffeb3b',style:'solid',width:2},
						expiries:{},
					};
					const EXPIRY_WAVE_SETTINGS_KEY = 'dankbit_expiry_wave_settings_v1';
					const DEFAULT_EXPIRY_WAVE_SETTINGS = { pathColor:'#26a69a', rangeColor:'#26a69a', pathStyle:'solid', pathWidth:3, showRange:true, showLabels:true };
					let expiryWaveSettings = Object.assign({}, DEFAULT_EXPIRY_WAVE_SETTINGS);
					try {
						const saved = JSON.parse(localStorage.getItem(EXPIRY_WAVE_SETTINGS_KEY) || '{}');
						if (/^#[0-9a-f]{6}$/i.test(saved.pathColor || '')) expiryWaveSettings.pathColor = saved.pathColor;
						if (/^#[0-9a-f]{6}$/i.test(saved.rangeColor || '')) expiryWaveSettings.rangeColor = saved.rangeColor;
						if (['solid','dashed','dotted'].includes(saved.pathStyle)) expiryWaveSettings.pathStyle = saved.pathStyle;
						if (Number.isFinite(parseInt(saved.pathWidth, 10))) expiryWaveSettings.pathWidth = Math.max(1, Math.min(5, parseInt(saved.pathWidth, 10)));
						if (typeof saved.showRange === 'boolean') expiryWaveSettings.showRange = saved.showRange;
						if (typeof saved.showLabels === 'boolean') expiryWaveSettings.showLabels = saved.showLabels;
					} catch (e) { /* Keep Expiry Wave defaults for malformed local settings. */ }
					const EXPIRY_TRACE_SETTINGS_KEY='dankbit_expiry_trace_line_settings';
					const DEFAULT_EXPIRY_TRACE_LINES={
						BCG:{color:'#2e7d32',style:'dashed',width:2},
						BPG:{color:'#c62828',style:'dashed',width:2},
						SCG:{color:'#7e57c2',style:'dashed',width:2},
						SPG:{color:'#1565c0',style:'dashed',width:2},
					};
					let expiryTraceLines=JSON.parse(JSON.stringify(DEFAULT_EXPIRY_TRACE_LINES));
					try{const saved=JSON.parse(localStorage.getItem(EXPIRY_TRACE_SETTINGS_KEY)||'{}');Object.keys(expiryTraceLines).forEach(k=>{const row=saved[k]||{};if(/^#[0-9a-f]{6}$/i.test(row.color||''))expiryTraceLines[k].color=row.color;if(['solid','dashed','dotted'].includes(row.style))expiryTraceLines[k].style=row.style;expiryTraceLines[k].width=Math.max(1,Math.min(5,parseInt(row.width,10)||expiryTraceLines[k].width));});}catch(e){}
					const MM_HEDGE_SETTINGS_KEY='dankbit_mm_hedge_line_settings';
					const DEFAULT_MM_HEDGE_LINES={short:{color:'#6a1b9a',style:'dashed',width:2},structural:{color:'#00838f',style:'solid',width:2},showLabels:true};
					let mmHedgeLineSettings=JSON.parse(JSON.stringify(DEFAULT_MM_HEDGE_LINES));
					try{const saved=JSON.parse(localStorage.getItem(MM_HEDGE_SETTINGS_KEY)||'{}');['short','structural'].forEach(k=>{const row=saved[k]||{};if(/^#[0-9a-f]{6}$/i.test(row.color||''))mmHedgeLineSettings[k].color=row.color;if(['solid','dashed','dotted'].includes(row.style))mmHedgeLineSettings[k].style=row.style;mmHedgeLineSettings[k].width=Math.max(1,Math.min(4,parseInt(row.width,10)||2));});if(typeof saved.showLabels==='boolean')mmHedgeLineSettings.showLabels=saved.showLabels;}catch(e){}
					let chartColors = Object.assign({}, DEFAULT_COLORS);
					let chartLineStyles = Object.assign({}, DEFAULT_LINE_STYLES);
					let gammaHorizonSettings = JSON.parse(JSON.stringify(DEFAULT_GAMMA_HORIZON_SETTINGS));
					let bandAdaptiveSmoothing = localStorage.getItem(BAND_SMOOTHING_STORAGE_KEY) !== 'false';
					// State is isolated per timeframe. Reusing a 1H ATR-derived buffer on
					// 4H/1D was visually smooth but mathematically inconsistent and made
					// the same raw bands depend on which timeframe the user viewed first.
					let bandSmoothingState = {};
					try { bandSmoothingState = JSON.parse(localStorage.getItem(BAND_SMOOTHING_STATE_KEY) || '{}'); }
					catch (e) { bandSmoothingState = {}; }
					let forecastCandleCounts = { '1h': 72, '4h': 18, '1d': 3 };
					try {
						const savedCounts = JSON.parse(localStorage.getItem(FORECAST_COUNT_STORAGE_KEY) || '{}');
						Object.keys(FORECAST_MAX_COUNTS).forEach(tf => {
							forecastCandleCounts[tf] = Math.max(1, Math.min(parseInt(savedCounts[tf], 10) || FORECAST_MAX_COUNTS[tf], FORECAST_MAX_COUNTS[tf]));
						});
					} catch (e) { /* malformed stored value — use timeframe defaults */ }
					try {
						const savedColors = JSON.parse(localStorage.getItem(COLOR_STORAGE_KEY) || '{}');
						// Preserve legacy upper/lower choices while separating Bands
						// from Smart Liquidity for all new saves.
						if (savedColors.highResistance) {
							savedColors.bandUpper = savedColors.bandUpper || savedColors.highResistance;
							savedColors.smartLiqUpper = savedColors.smartLiqUpper || savedColors.highResistance;
						}
						if (savedColors.lowSupport) {
							savedColors.bandLower = savedColors.bandLower || savedColors.lowSupport;
							savedColors.smartLiqLower = savedColors.smartLiqLower || savedColors.lowSupport;
						}
						Object.keys(DEFAULT_COLORS).forEach(key => {
							if (savedColors[key]) chartColors[key] = savedColors[key];
						});
					} catch (e) { /* malformed/legacy stored value — fall back to defaults */ }
					try {
						const savedStyles = JSON.parse(localStorage.getItem(LINE_STYLE_STORAGE_KEY) || '{}');
						Object.keys(DEFAULT_LINE_STYLES).forEach(key => {
							if (['solid', 'dashed', 'dotted'].includes(savedStyles[key])) chartLineStyles[key] = savedStyles[key];
						});
					} catch (e) { /* malformed stored value — fall back to defaults */ }
					try {
						const saved = JSON.parse(localStorage.getItem(GAMMA_HORIZON_SETTINGS_KEY) || '{}');
						['D1', 'W', 'M', 'YE'].forEach(kind => {
							const row = saved[kind] || {};
							if (typeof row.visible === 'boolean') gammaHorizonSettings[kind].visible = row.visible;
							if (/^#[0-9a-f]{6}$/i.test(row.color || '')) gammaHorizonSettings[kind].color = row.color;
							if (['solid', 'dashed', 'dotted'].includes(row.style)) gammaHorizonSettings[kind].style = row.style;
							gammaHorizonSettings[kind].width = Math.max(1, Math.min(4, parseInt(row.width, 10) || gammaHorizonSettings[kind].width));
						});
						const savedWeeklyCount = parseInt(saved.weeklyCount, 10);
						const savedMonthlyCount = parseInt(saved.monthlyCount, 10);
						if (Number.isFinite(savedWeeklyCount)) gammaHorizonSettings.weeklyCount = Math.max(0, Math.min(3, savedWeeklyCount));
						if (Number.isFinite(savedMonthlyCount)) gammaHorizonSettings.monthlyCount = Math.max(0, Math.min(3, savedMonthlyCount));
						if (typeof saved.showLabels === 'boolean') gammaHorizonSettings.showLabels = saved.showLabels;
						if (typeof saved.showGreeks === 'boolean') gammaHorizonSettings.showGreeks = saved.showGreeks;
						if (saved.recent && typeof saved.recent === 'object') {
							if (/^#[0-9a-f]{6}$/i.test(saved.recent.color||'')) gammaHorizonSettings.recent.color=saved.recent.color;
							if (['solid','dashed','dotted'].includes(saved.recent.style)) gammaHorizonSettings.recent.style=saved.recent.style;
							gammaHorizonSettings.recent.width=Math.max(1,Math.min(4,parseInt(saved.recent.width,10)||2));
						}
						if (saved.expiries && typeof saved.expiries === 'object') {
							Object.keys(saved.expiries).forEach(expiry => {
								const row=saved.expiries[expiry] || {};
								gammaHorizonSettings.expiries[expiry]={
									visible:row.visible !== false,
									color:/^#[0-9a-f]{6}$/i.test(row.color||'')?row.color:null,
									style:['solid','dashed','dotted'].includes(row.style)?row.style:null,
									width:Math.max(1,Math.min(4,parseInt(row.width,10)||1)),
									mode:['structural','recent','compare'].includes(row.mode)?row.mode:'structural',
								};
							});
						}
					} catch (e) { /* malformed stored value — use Gamma Horizon defaults */ }

					function lineStyleFromName(name) {
						if (name === 'dashed') return LightweightCharts.LineStyle.Dashed;
						if (name === 'dotted') return LightweightCharts.LineStyle.Dotted;
						return LightweightCharts.LineStyle.Solid;
					}

					function hexToRgba(hex, alpha) {
						const h = hex.replace('#', '');
						const r = parseInt(h.substring(0, 2), 16);
						const g = parseInt(h.substring(2, 4), 16);
						const b = parseInt(h.substring(4, 6), 16);
						return 'rgba(' + r + ',' + g + ',' + b + ',' + alpha + ')';
					}

					const GAMMA_HORIZON_URL = '/api/gamma-horizon/' + ASSET;
					const STRATEGY_RADAR_URL = '/api/option-strategy-radar/' + ASSET;
					const EXPIRY_PRICING_URL = '/api/expiry-pricing/' + ASSET;
					const EXPIRY_TRACE_EXPIRIES_URL = '/api/expiry-trace/expiries/' + ASSET;
					const MM_HEDGE_URL = '/api/mm-hedge/' + ASSET;
					const EXPIRY_WAVE_URL = '/api/expiry-wave/' + ASSET;
					const BANDS_URL        = '/api/bands/' + ASSET;
					const LIVE_BAND_URL    = '/api/live-band/' + ASSET;
					const ZB_URL           = '/api/zones-box/' + ASSET;
					const NEAREST_EXPIRY_URL = '/api/nearest-expiry/' + ASSET;
					const LAST_TRADE_URL   = '/api/last-trade/' + ASSET;
					const FORECAST_URL    = '/api/forecast/' + ASSET;
					const SIGNAL_BOT_URL  = '/api/signal-bot/' + ASSET;
					// "Thales Forecast" checkbox (Delta Chart only — after
					// "Bands"; the Gamma Chart no longer has this
					// checkbox at all, so SHOW_FORECAST simply never gets
					// set true there) — unchecked by default, same server-
					// load-reducing pattern as every other optional indicator on
					// this chart.
					// Draws a fully deterministic path (see FORECAST_URL) ported
					// from Thales's own forecast-candle engine — see forecast.py.
					let SHOW_FORECAST = false;
					let SHOW_RSI = false;
					let SHOW_SIGNAL_BOT = false;
					let SIGNAL_BOT_DETAILS_OPEN = false;
					let latestSignalBotData = null;
					let signalBotPriceLines = [];
					let signalBotRequestSeq = 0;
					let   INTERVAL         = '4h';
					const klineUrl   = (iv, limit) => '/api/klines/' + ASSET + '?interval=' + iv + '&limit=' + limit;

					// Lightweight Charts has no native IANA-timezone support — it always
					// renders epoch seconds as UTC wall-clock time. To display any other
					// zone, every timestamp fed into the chart is pre-shifted by that
					// zone's current UTC offset (DST-aware, since it's computed against
					// "now"), and localization.timeFormatter below formats with
					// timeZone: 'UTC' so the shifted epoch reads as real wall-clock time.
					// The zone itself is auto-detected from the browser rather than
					// hardcoded, falling back to UTC (offset 0) if detection ever fails.
					const tzOffset = (() => {
						let zone;
						try {
							zone = Intl.DateTimeFormat().resolvedOptions().timeZone;
						} catch (e) {
							return 0;
						}
						const d = new Date();
						const utc = new Date(d.toLocaleString('en-US', { timeZone: 'UTC' }));
						const local = new Date(d.toLocaleString('en-US', { timeZone: zone }));
						return (local - utc) / 1000;
					})();

					const chart = LightweightCharts.createChart(document.getElementById('chart-container'), {
						width: window.innerWidth, height: window.innerHeight,
						// Colors already reflect DARK_MODE (a saved localStorage
						// preference from a prior visit, or the light-mode default)
						// so a returning dark-mode user doesn't see a light flash
						// before applyTheme() would otherwise run — see DARK_MODE above.
						layout: {
							background: { type: 'solid', color: DARK_MODE ? '#000000' : '#ffffff' },
							textColor: DARK_MODE ? '#d1d4dc' : '#333333',
						},
						grid: { vertLines: { visible: false }, horzLines: { visible: false } },
						crosshair: { mode: LightweightCharts.CrosshairMode.Normal, horzLine: { labelBackgroundColor: 'blue' } },
						rightPriceScale: { borderColor: DARK_MODE ? '#444444' : '#cccccc' },
						timeScale: { borderColor: DARK_MODE ? '#444444' : '#cccccc', timeVisible: true, secondsVisible: false },
						localization: {
							timeFormatter: ts => new Date(ts * 1000).toLocaleString('de-DE', {
								timeZone: 'UTC',
								month: 'short', day: 'numeric',
								hour: '2-digit', minute: '2-digit',
							}),
						},
					});

					const rsiChart = LightweightCharts.createChart(document.getElementById('rsi-container'), {
						width: window.innerWidth, height: Math.round(window.innerHeight * 0.22),
						layout: { background:{ type:'solid', color:DARK_MODE ? '#000000' : '#ffffff' }, textColor:DARK_MODE ? '#d1d4dc' : '#333333' },
						grid: { vertLines:{ visible:false }, horzLines:{ visible:false } },
						crosshair: { mode:LightweightCharts.CrosshairMode.Normal },
						rightPriceScale: { borderColor:DARK_MODE ? '#444444' : '#cccccc', scaleMargins:{ top:0.08, bottom:0.08 } },
						timeScale: { borderColor:DARK_MODE ? '#444444' : '#cccccc', timeVisible:true, secondsVisible:false },
					});
					const rsiSeries = rsiChart.addLineSeries({ color:'#7e57c2', lineWidth:2, lastValueVisible:true, priceLineVisible:false });
					const rsiMaSeries = rsiChart.addLineSeries({ color:'#d4af37', lineWidth:2, lastValueVisible:true, priceLineVisible:false });
					[30, 50, 70].forEach(value => rsiSeries.createPriceLine({ price:value, color:value === 50 ? '#777777' : '#999999', lineWidth:1, lineStyle:LightweightCharts.LineStyle.Dashed, axisLabelVisible:true, title:String(value) }));
					function resizeCharts() {
						const rsiHeight = SHOW_RSI ? Math.round(window.innerHeight * 0.22) : 0;
						chart.resize(window.innerWidth, window.innerHeight - rsiHeight);
						if (SHOW_RSI) rsiChart.resize(window.innerWidth, rsiHeight);
					}
					window.addEventListener('resize', resizeCharts);
					// #tf-bar wraps onto extra rows on a narrow viewport (see its
					// own CSS comment) — every fixed-position element stacked
					// underneath it tracks its actual measured bottom edge via
					// this custom property instead of a hardcoded offset, so a
					// taller (wrapped) toolbar can never overlap them. Re-run on
					// resize (row count can change) and after
					// updateForecastVisibility() toggles #forecast-toggle-wrap,
					// since that can change the toolbar's height independent of
					// any resize event.
					function repositionBelowToolbar() {
						const bar = document.getElementById('tf-bar');
						if (!bar) return;
						const bottom = Math.ceil(bar.getBoundingClientRect().bottom);
						document.documentElement.style.setProperty('--tf-bar-bottom', bottom + 'px');
					}
					window.addEventListener('resize', repositionBelowToolbar);
					repositionBelowToolbar();
					let syncingTimeScale = false;
					chart.timeScale().subscribeVisibleLogicalRangeChange(range => {
						if (!SHOW_RSI || !range || syncingTimeScale) return;
						syncingTimeScale = true; rsiChart.timeScale().setVisibleLogicalRange(range); syncingTimeScale = false;
					});
					rsiChart.timeScale().subscribeVisibleLogicalRangeChange(range => {
						if (!SHOW_RSI || !range || syncingTimeScale) return;
						syncingTimeScale = true; chart.timeScale().setVisibleLogicalRange(range); syncingTimeScale = false;
					});

					const series = chart.addCandlestickSeries({
						upColor: '#26a69a', downColor: '#ef5350',
						borderVisible: false, wickUpColor: '#26a69a', wickDownColor: '#ef5350',
					});

					// Invisible helper series solely to extend the shared time axis
					// FUTURE_MARGIN_DAYS past the last real candle, with labeled tick
					// marks. Candlestick setData() silently drops OHLC-less
					// "whitespace" points (confirmed empirically — a 30-point future
					// whitespace array passed alongside real candles left
					// series.data().length unchanged), so a real, fully-valued (if
					// invisible) line series is used instead; all series on a chart
					// share one time scale, so its future points extend the same axis
					// the candlesticks are drawn on.
					const futureAxisSeries = chart.addLineSeries({
						color: 'rgba(0,0,0,0)', lineWidth: 1,
						lastValueVisible: false, priceLineVisible: false, crosshairMarkerVisible: false,
					});

					const gammaBandSeries = chart.addLineSeries({ color: chartColors.gammaBand, lineWidth: 2, lineStyle: lineStyleFromName(chartLineStyles.gammaBand), lastValueVisible: false, priceLineVisible: false });
					// Pure Thales Bands: Green/Red are always the upper/lower
					// Longs-vs-Shorts curve intersections. They are not averaged with
					// Smart Liquidity.
					const bandUpperSeries = chart.addLineSeries({ color: chartColors.bandUpper, lineWidth: 2, lineStyle: lineStyleFromName(chartLineStyles.bandUpper), lastValueVisible: false, priceLineVisible: false });
					const bandLowerSeries = chart.addLineSeries({ color: chartColors.bandLower, lineWidth: 2, lineStyle: lineStyleFromName(chartLineStyles.bandLower), lastValueVisible: false, priceLineVisible: false });
					// Unconfirmed E1/E2/E3 anchors use separate dashed series. They
					// extend the structural path without visually claiming confirmation.
					const bandUpperProvisionalSeries = chart.addLineSeries({ color: hexToRgba(chartColors.bandUpper, 0.68), lineWidth: 2, lineStyle: LightweightCharts.LineStyle.Dashed, lastValueVisible: false, priceLineVisible: false });
					const bandLowerProvisionalSeries = chart.addLineSeries({ color: hexToRgba(chartColors.bandLower, 0.68), lineWidth: 2, lineStyle: LightweightCharts.LineStyle.Dashed, lastValueVisible: false, priceLineVisible: false });
					// Smart Liquidity remains available, but as a separate optional layer.
					// Dominance used to be drawn as a second, thicker line series shown
					// only on the dominant side's own points (the rest left as blank
					// "whitespace" points). Lightweight Charts v4 does NOT break a line at
					// a whitespace point, though — confirmed empirically: it silently
					// connects straight through to the next real value, however many
					// blanks sit in between. Wherever dominance flipped more than once,
					// that produced a false extra diagonal connecting non-adjacent points,
					// which is what was reading as "two lines". Dominance is instead shown
					// via setMarkers() on this single line (see smartLiqDominanceMarkers) —
					// a bigger dot on the dominant side's own points, nothing on the other
					// side — since markers don't rely on whitespace-breaks at all.
					const smartLiqUpperSeries = chart.addLineSeries({ color: hexToRgba(chartColors.smartLiqUpper, 0.55), lineWidth: 2, lineStyle: lineStyleFromName(chartLineStyles.smartLiqUpper), lastValueVisible: false, priceLineVisible: false, crosshairMarkerVisible: false });
					const smartLiqLowerSeries = chart.addLineSeries({ color: hexToRgba(chartColors.smartLiqLower, 0.55), lineWidth: 2, lineStyle: lineStyleFromName(chartLineStyles.smartLiqLower), lastValueVisible: false, priceLineVisible: false, crosshairMarkerVisible: false });
					// Per-hour Smart Liquidity dominance dots — same "Bands"
					// checkbox, a separate data source from the two lines above:
					// dankbit.live.band's hourly append-only log
					// (/api/live-band/<asset>), not dankbit.bands' per-instrument
					// term structure. One dot per hour/candle bucket for
					// whichever side (smart_liq_upper/smart_liq_lower) was
					// dominant that hour — deliberately NOT connected into a
					// line (transparent line color, same belt-and-suspenders
					// technique as every other dominant-point indicator in this
					// addon — lineVisible:false alone isn't enough to guarantee
					// no line renders). Same green/red as the lines above.
					const liveBandUpperSeries = chart.addLineSeries({
						color: 'rgba(0,0,0,0)', lineWidth: 1, lineVisible: false,
						lastValueVisible: false, priceLineVisible: false, crosshairMarkerVisible: false,
					});
					const liveBandLowerSeries = chart.addLineSeries({
						color: 'rgba(0,0,0,0)', lineWidth: 1, lineVisible: false,
						lastValueVisible: false, priceLineVisible: false, crosshairMarkerVisible: false,
					});

					// Zones boxes: filled rectangles marking the above-price and below-price
					// zero-crossing zones, using addBaselineSeries's flat top-line + baseValue
					// fill (the "line" is a constant top price, filled down to a constant
					// baseValue bottom price) to fake a bounded rectangle Lightweight Charts
					// has no native primitive for.
					const aboveBoxSeries = chart.addBaselineSeries({
						baseValue: { type: 'price', price: 0 },
						topLineColor: chartColors.zonesBox, topFillColor1: hexToRgba(chartColors.zonesBox, 0.25), topFillColor2: hexToRgba(chartColors.zonesBox, 0.25),
						bottomLineColor: chartColors.zonesBox, bottomFillColor1: hexToRgba(chartColors.zonesBox, 0.25), bottomFillColor2: hexToRgba(chartColors.zonesBox, 0.25),
						lineWidth: 1, lastValueVisible: false, priceLineVisible: false, crosshairMarkerVisible: false,
					});
					const belowBoxSeries = chart.addBaselineSeries({
						baseValue: { type: 'price', price: 0 },
						topLineColor: chartColors.zonesBox, topFillColor1: hexToRgba(chartColors.zonesBox, 0.25), topFillColor2: hexToRgba(chartColors.zonesBox, 0.25),
						bottomLineColor: chartColors.zonesBox, bottomFillColor1: hexToRgba(chartColors.zonesBox, 0.25), bottomFillColor2: hexToRgba(chartColors.zonesBox, 0.25),
						lineWidth: 1, lastValueVisible: false, priceLineVisible: false, crosshairMarkerVisible: false,
					});
					// addBaselineSeries only strokes its top edge; add a plain line series
					// for the bottom edge so both edges get the same visible border.
					const aboveBoxBottomLine = chart.addLineSeries({ color: chartColors.zonesBox, lineWidth: 1, lastValueVisible: false, priceLineVisible: false, crosshairMarkerVisible: false });
					const belowBoxBottomLine = chart.addLineSeries({ color: chartColors.zonesBox, lineWidth: 1, lastValueVisible: false, priceLineVisible: false, crosshairMarkerVisible: false });

					// Seller Max Profit / Buyer Max Loss box — same left/right time edges as the yellow
					// box above (both come from the same get_box() call for the nearest
					// expiry), teal so it stays visually distinct from yellow/violet/
					// green. setBoxData() already draws a single line instead of a box
					// when top and bottom coincide (or only one is available).
					const smpBmlBoxSeries = chart.addBaselineSeries({
						baseValue: { type: 'price', price: 0 },
						topLineColor: chartColors.middleZone, topFillColor1: hexToRgba(chartColors.middleZone, 0.25), topFillColor2: hexToRgba(chartColors.middleZone, 0.25),
						bottomLineColor: chartColors.middleZone, bottomFillColor1: hexToRgba(chartColors.middleZone, 0.25), bottomFillColor2: hexToRgba(chartColors.middleZone, 0.25),
						lineWidth: 1, lastValueVisible: false, priceLineVisible: false, crosshairMarkerVisible: false,
					});
					const smpBmlBoxBottomLine = chart.addLineSeries({ color: chartColors.middleZone, lineWidth: 1, lastValueVisible: false, priceLineVisible: false, crosshairMarkerVisible: false });

					// Thales Forecast candles ("Thales Forecast" checkbox) —
					// Thales's deterministic forecast-candle engine (see
					// forecast.py), sourced from /api/forecast/<asset>. Light
					// red/green (user-configurable, see FORECAST_UP_COLOR etc.
					// above) so it stays easily distinguishable from the real
					// candles' own teal/red at a glance.
					const forecastSeries = chart.addCandlestickSeries({
						upColor: chartColors.forecastUp, downColor: chartColors.forecastDown, borderVisible: false,
						wickUpColor: chartColors.forecastWickUp, wickDownColor: chartColors.forecastWickDown,
						lastValueVisible: false, priceLineVisible: false,
					});

					let gammaHorizonLines = [];
					let gammaHorizonLineMeta = [];
					let gammaHorizonData = null;
					let pinnedGreeksHorizonKey = null;

					function clearLines(arr) {
						arr.forEach(pl => series.removePriceLine(pl));
						arr.length = 0;
					}

					function setStatus(text) { document.getElementById('status').textContent = text; }

					function toCandle(k) {
						return { time: Math.floor(k.t / 1000) + tzOffset, open: parseFloat(k.o), high: parseFloat(k.h), low: parseFloat(k.l), close: parseFloat(k.c) };
					}

					// Daily Forecast spans only three days; a one-year initial window
					// compressed all current curves/candles into a thin strip.
					const TF_WINDOW = { '1h': 30, '4h': 15, '1d': 90 };
					const BARS_PER_DAY = { '1h': 24, '4h': 6, '1d': 1 };
					const INTERVAL_SECONDS = { '1h': 3600, '4h': 4 * 3600, '1d': 86400 };

					const FUTURE_MARGIN_DAYS = 5;

					// realCandles.length + futureTickCount is the current total
					// logical bar count across both series sharing the time axis —
					// tracked directly rather than re-derived from series.data(),
					// since the candlestick series' own data() only ever reflects
					// realCandles (see futureAxisSeries above).
					let realCandles = [];
					let futureTickCount = 0;

					function applyVisibleRange() {
						const days = TF_WINDOW[INTERVAL] || 21;
						const barsPerDay = BARS_PER_DAY[INTERVAL] || 24;
						const lastIndex = realCandles.length + futureTickCount - 1;
						const range = {
							from: lastIndex - days * barsPerDay,
							to:   lastIndex,
						};
						chart.timeScale().setVisibleLogicalRange(range);
						if (SHOW_RSI) rsiChart.timeScale().setVisibleLogicalRange(range);
					}

					function refreshRsi() {
						const period = 14;
						if (realCandles.length <= period) { rsiSeries.setData([]); rsiMaSeries.setData([]); return; }
						const values = [];
						let gain = 0, loss = 0;
						for (let i = 1; i <= period; i++) {
							const delta = realCandles[i].close - realCandles[i - 1].close;
							gain += Math.max(delta, 0); loss += Math.max(-delta, 0);
						}
						gain /= period; loss /= period;
						const pushValue = i => values.push({ time:realCandles[i].time, value:loss === 0 ? 100 : 100 - 100 / (1 + gain / loss) });
						pushValue(period);
						for (let i = period + 1; i < realCandles.length; i++) {
							const delta = realCandles[i].close - realCandles[i - 1].close;
							gain = (gain * (period - 1) + Math.max(delta, 0)) / period;
							loss = (loss * (period - 1) + Math.max(-delta, 0)) / period;
							pushValue(i);
						}
						rsiSeries.setData(values);
						const ma = values.map((point, i) => i < period - 1 ? null : ({ time:point.time, value:values.slice(i - period + 1, i + 1).reduce((sum, row) => sum + row.value, 0) / period })).filter(Boolean);
						rsiMaSeries.setData(ma);
					}

					function onToggleRsi() {
						SHOW_RSI = Boolean(document.getElementById('rsi-toggle')?.checked);
						document.body.classList.toggle('rsi-visible', SHOW_RSI);
						resizeCharts();
						if (SHOW_RSI) { refreshRsi(); applyVisibleRange(); }
					}

					// Right-click "Reset chart view" — mirrors original TradingView's
					// context-menu item: re-autoscales the price axis (undoes any
					// manual drag-zoom on the price scale) and restores the default
					// time-scale window for the current timeframe (undoes any
					// pan/zoom on the time axis), without touching series data or any
					// indicator toggle state.
					function resetChartView() {
						chart.priceScale('right').applyOptions({ autoScale: true });
						applyVisibleRange();
					}

					// Custom context menu (Lightweight Charts has no built-in one) —
					// right-clicking the chart area shows a single "Reset chart view"
					// item at the cursor, clamped so it never renders off-screen.
					const contextMenu = document.getElementById('context-menu');

					function hideContextMenu() {
						contextMenu.style.display = 'none';
					}

					function showContextMenu(x, y) {
						contextMenu.style.display = 'block';
						const maxX = window.innerWidth - contextMenu.offsetWidth - 4;
						const maxY = window.innerHeight - contextMenu.offsetHeight - 4;
						contextMenu.style.left = Math.min(x, maxX) + 'px';
						contextMenu.style.top = Math.min(y, maxY) + 'px';
					}

					function onResetChartViewClick() {
						resetChartView();
						hideContextMenu();
					}

					const chartContainerEl = document.getElementById('chart-container');
					chartContainerEl.addEventListener('contextmenu', e => {
						e.preventDefault();
						showContextMenu(e.clientX, e.clientY);
					});
					// Right-clicking outside the chart area (e.g. the toolbar) falls
					// through to the browser's own native context menu — hide ours
					// first so it doesn't linger open underneath it.
					document.addEventListener('contextmenu', e => {
						if (!chartContainerEl.contains(e.target)) hideContextMenu();
					});
					document.addEventListener('click', hideContextMenu);
					window.addEventListener('resize', hideContextMenu);
					window.addEventListener('scroll', hideContextMenu, true);

					function rebuildSeriesData() {
						series.setData(realCandles);

						const intervalSec = INTERVAL_SECONDS[INTERVAL] || 3600;
						const lastClose = realCandles.length ? realCandles[realCandles.length - 1].close : 0;
						const lastTime = realCandles.length
							? realCandles[realCandles.length - 1].time
							: (Math.floor(Date.now() / 1000) + tzOffset);
						const count = Math.round(FUTURE_MARGIN_DAYS * 86400 / intervalSec);
						const futureTicks = [];
						for (let i = 1; i <= count; i++) {
							futureTicks.push({ time: lastTime + i * intervalSec, value: lastClose });
						}
						futureTickCount = futureTicks.length;
						futureAxisSeries.setData(futureTicks);
					}

					async function loadCandles() {
						const resp = await (await fetch(klineUrl(INTERVAL, 500))).json();
						const klines = (resp.result || []).slice().reverse();
						realCandles = klines.map(toCandle);
						rebuildSeriesData();
						refreshRsi();
						applyVisibleRange();
					}

					async function updateLatestCandle() {
						const resp = await (await fetch(klineUrl(INTERVAL, 2))).json();
						const klines = resp.result || [];
						if (!klines.length) return;
						const updated = toCandle(klines[0]);
						if (realCandles.length && realCandles[realCandles.length - 1].time === updated.time) {
							realCandles[realCandles.length - 1] = updated;
						} else {
							realCandles.push(updated);
						}
						rebuildSeriesData();
						refreshRsi();
					}

					async function setTf(iv) {
						INTERVAL = iv;
						await loadCandles();
						await refreshBands();
						await refreshLiveBandDots();
						await refreshZonesBoxes();
						await updateForecastVisibility();
					}

					function gammaHorizonLabel(item) {
						if (!gammaHorizonSettings.showLabels) return '';
						const expiry = new Date(item.expiry);
						const date = expiry.toLocaleDateString('en-GB', {
							timeZone:'UTC', day:'2-digit', month:'short', year:'2-digit',
						}).toUpperCase().replace(/ /g, ' ');
						const price=Number(item.price).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});
						const analysis=gammaHorizonSettings.showGreeks && item.greeks
							? ' · '+item.greeks.regime.replace(' UP',' ↑').replace(' DOWN',' ↓')+' '+Number(item.greeks.confidence)+'%'
							: '';
						return item.kind+' · '+date+' · '+price+analysis;
					}

					function gammaHorizonRecentLabel(item) {
						if (!gammaHorizonSettings.showLabels || !Number.isFinite(Number(item.recent?.price))) return '';
						const date=new Date(item.expiry).toLocaleDateString('en-GB',{timeZone:'UTC',day:'2-digit',month:'short',year:'2-digit'}).toUpperCase();
						const price=Number(item.recent.price).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2});
						const signal=item.repricing?.signal||'RECENT';const confidence=Number(item.repricing?.confidence||0);
						return item.kind+' · '+date+' · RECENT '+price+' · '+signal.replace('BULLISH','↑').replace('BEARISH','↓')+' '+confidence+'%';
					}

					function gammaHorizonAppearance(item) {
						const base=gammaHorizonSettings[item.kind]||gammaHorizonSettings.W;
						const own=gammaHorizonSettings.expiries?.[item.expiry]||{};
						return {visible:own.visible!==false,mode:own.mode||'structural',color:own.color||base.color,style:own.style||base.style,width:own.width||base.width};
					}

					function ghFmt(value,digits) {
						if(value==null)return '—'; const n=Number(value); const d=digits==null?0:digits;
						return Number.isFinite(n)?n.toLocaleString(undefined,{minimumFractionDigits:d,maximumFractionDigits:d}):'—';
					}

					function greeksHorizonTooltipHtml(items) {
						return items.map(item=>{const g=item.greeks||{},s=g.scores||{},theta=g.theta||{},vega=g.vega||{},iv=g.iv||{},pc=g.price_context||{},r=item.repricing||{},recent=item.recent||{};const date=new Date(item.expiry).toLocaleDateString('en-GB',{timeZone:'UTC',day:'2-digit',month:'short',year:'numeric'}).toUpperCase();const migration=g.level_migration==null?'—':(Number(g.level_migration)>=0?'+':'')+ghFmt(g.level_migration,2);const layer=item._hoverLayer==='recent'?'RECENT':'STRUCTURAL';const shown=item._hoverPrice==null?item.price:item._hoverPrice;const shift=Number(r.shift)>=0?'+':'−';return '<div class="gh-tip-title">'+radarEsc(item.kind)+' · '+date+' · '+layer+' '+ghFmt(shown,2)+'</div><div class="gh-tip-regime">'+radarEsc(r.signal||g.regime||'GAMMA ONLY')+' · Repricing confidence '+ghFmt(r.confidence)+'%</div><div class="gh-tip-grid"><span>Structural Gamma</span><b>'+ghFmt(item.price,2)+'</b><span>Recent Gamma</span><b>'+ghFmt(recent.price,2)+'</b><span>Recent window</span><b>'+ghFmt(Number(recent.window_hours||0)/24,1)+' days</b><span>Gamma shift</span><b>'+shift+ghFmt(Math.abs(Number(r.shift||0)),2)+' ('+(Number(r.shift_pct)>=0?'+':'')+ghFmt(r.shift_pct,2)+'%)</b><span>Shift distance</span><b>'+ghFmt(r.shift_atr,2)+' ATR</b><span>Recent share</span><b>'+ghFmt(r.recent_share_pct,1)+'%</b><span>Recent trades</span><b>'+ghFmt(recent.trade_count)+'</b></div><div class="gh-tip-scores"><div class="gh-tip-score">Attract<br/><b>'+ghFmt(s.attraction)+'</b></div><div class="gh-tip-score">Hold<br/><b>'+ghFmt(s.hold)+'</b></div><div class="gh-tip-score">Pin<br/><b>'+ghFmt(s.pin)+'</b></div><div class="gh-tip-score">Break<br/><b>'+ghFmt(s.break)+'</b></div></div><div class="gh-tip-grid"><span>Stage</span><b>'+radarEsc(g.stage||'—')+'</b><span>Distance</span><b>'+ghFmt(pc.distance_atr,2)+' ATR</b><span>Level migration</span><b>'+migration+'</b><span>Theta control</span><b>'+(Number(theta.control)>=0?'Seller +':'Buyer ')+ghFmt(Math.abs(Number(theta.control||0)),1)+'</b><span>Net Vega</span><b>'+ghFmt(vega.net,2)+'</b><span>IV trend</span><b>'+radarEsc(iv.trend||'—')+' '+(Number(iv.change_points)>=0?'+':'')+ghFmt(iv.change_points,2)+'</b><span>Structural trades</span><b>'+ghFmt(item.trade_count)+'</b><span>Data quality</span><b>'+ghFmt(g.data_quality)+'%</b></div><div class="gh-tip-note">Gamma Repricing is display-only and does not feed Forecast or any other engine.</div>';}).join('<hr style="border:0;border-top:1px solid #777;margin:8px 0"/>');
					}

					function nearbyGammaHorizonItems(point) {
						if(!point)return[];
						return gammaHorizonLineMeta.map(meta=>({meta,y:series.priceToCoordinate(Number(meta.price))})).filter(row=>row.y!==null&&Math.abs(row.y-point.y)<=8).sort((a,b)=>Math.abs(a.y-point.y)-Math.abs(b.y-point.y)).map(row=>Object.assign({},row.meta.item,{_hoverLayer:row.meta.layer,_hoverPrice:row.meta.price}));
					}

					function showGreeksHorizonTooltip(items,point,force) {
						const tip=document.getElementById('greeks-horizon-tooltip');if(!tip)return;
						if(!items.length){if(!pinnedGreeksHorizonKey||force)tip.style.display='none';return;}
						tip.innerHTML=greeksHorizonTooltipHtml(items);tip.style.display='block';
						const rect=document.getElementById('chart-container').getBoundingClientRect();let left=rect.left+point.x+14,top=rect.top+point.y+14;
						if(left+tip.offsetWidth>window.innerWidth-8)left=rect.left+point.x-tip.offsetWidth-14;if(top+tip.offsetHeight>window.innerHeight-8)top=window.innerHeight-tip.offsetHeight-8;
						tip.style.left=Math.max(8,left)+'px';tip.style.top=Math.max(8,top)+'px';
					}

					function enrichAndStoreGreeksHorizon(data) {
						try {
							let snapshots=JSON.parse(localStorage.getItem(GREEKS_HORIZON_SNAPSHOT_KEY)||'[]');if(!Array.isArray(snapshots))snapshots=[];
							const previous=snapshots[snapshots.length-1];
							(data.levels||[]).forEach(item=>{const old=(previous?.levels||[]).find(row=>row.expiry===item.expiry);if(item.greeks)item.greeks.level_migration=old?Number(item.price)-Number(old.price):null;});
							const bucket=Math.floor(new Date(data.generated_at).getTime()/900000);
							if(!snapshots.some(row=>row.bucket===bucket))snapshots.push({bucket,generated_at:data.generated_at,levels:(data.levels||[]).map(item=>({expiry:item.expiry,kind:item.kind,price:item.price,regime:item.greeks?.regime,confidence:item.greeks?.confidence,scores:item.greeks?.scores}))});
							localStorage.setItem(GREEKS_HORIZON_SNAPSHOT_KEY,JSON.stringify(snapshots.slice(-512)));
						} catch(e) { console.warn('Greeks Horizon snapshot unavailable',e); }
					}

					async function refreshGammaHorizon(settingsOnly) {
						if (MINIMAL_CHART || (!SHOW_GAMMA_HORIZON && !settingsOnly)) return;
						const response = await fetch(GAMMA_HORIZON_URL);
						if (!response.ok) throw new Error('Gamma Horizon HTTP ' + response.status);
						const data = await response.json();
						enrichAndStoreGreeksHorizon(data);
						gammaHorizonData=data;
						renderGammaHorizonExpirySettings();
						if (!SHOW_GAMMA_HORIZON || settingsOnly) return;
						clearLines(gammaHorizonLines);
						gammaHorizonLineMeta=[];
						(data.levels || []).forEach(item => {
							if (!Number.isFinite(Number(item.price))) return;
							const appearance = gammaHorizonAppearance(item);
							if (!appearance.visible) return;
							if(appearance.mode!=='recent'){
								const line=series.createPriceLine({price:Number(item.price),color:appearance.color,lineWidth:appearance.width,lineStyle:lineStyleFromName(appearance.style),axisLabelVisible:true,axisLabelColor:appearance.color,title:gammaHorizonLabel(item)});
								gammaHorizonLines.push(line);gammaHorizonLineMeta.push({line,item,appearance,price:Number(item.price),layer:'structural'});
							}
							if(appearance.mode!=='structural'&&Number.isFinite(Number(item.recent?.price))){
								const rcfg=gammaHorizonSettings.recent;const recentLine=series.createPriceLine({price:Number(item.recent.price),color:rcfg.color,lineWidth:rcfg.width,lineStyle:lineStyleFromName(rcfg.style),axisLabelVisible:true,axisLabelColor:rcfg.color,title:gammaHorizonRecentLabel(item)});
								gammaHorizonLines.push(recentLine);gammaHorizonLineMeta.push({line:recentLine,item,appearance:rcfg,price:Number(item.recent.price),layer:'recent'});
							}
						});
						lastTradeCount = Number(data.trade_count || 0);
						updateStatusLine();
					}

					function onToggleGammaHorizon() {
						SHOW_GAMMA_HORIZON = Boolean(document.getElementById('gamma-horizon-toggle')?.checked);
						if (SHOW_GAMMA_HORIZON) safeRefresh('Gamma Horizon', refreshGammaHorizon);
						else { clearLines(gammaHorizonLines); gammaHorizonLineMeta=[]; pinnedGreeksHorizonKey=null; const tip=document.getElementById('greeks-horizon-tooltip');if(tip)tip.style.display='none'; }
					}

					let SHOW_STRATEGY_RADAR = false;
					let strategyRadarData = null;
					let selectedStrategyRadarId = null;

					function radarEsc(value) {
						return String(value == null ? '' : value).replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
					}

					function radarMoney(value) {
						const number = Number(value || 0);
						return (number >= 0 ? '+' : '−') + '$' + Math.abs(number).toLocaleString(undefined, {maximumFractionDigits:0});
					}

					function radarDate(value, withTime) {
						if (!value) return '—';
						return new Date(value).toLocaleString('en-GB', {
							timeZone:'UTC', day:'2-digit', month:'short', year:'2-digit',
							hour:withTime ? '2-digit' : undefined, minute:withTime ? '2-digit' : undefined,
						}).toUpperCase() + (withTime ? ' UTC' : '');
					}

					function payoffSvg(strategy) {
						const points = strategy.payoff || [];
						if (points.length < 2) return '<div class="strategy-note">No payoff curve available.</div>';
						const width=640, height=260, left=58, right=18, top=18, bottom=38;
						const xs=points.map(p=>Number(p.price)), ys=points.map(p=>Number(p.value));
						const minX=Math.min(...xs), maxX=Math.max(...xs);
						let minY=Math.min(0,...ys), maxY=Math.max(0,...ys);
						if (maxY === minY) { maxY += 1; minY -= 1; }
						const pad=(maxY-minY)*0.08; minY-=pad; maxY+=pad;
						const sx=x=>left+(x-minX)/(maxX-minX)*(width-left-right);
						const sy=y=>top+(maxY-y)/(maxY-minY)*(height-top-bottom);
						const poly=points.map(p=>sx(Number(p.price)).toFixed(1)+','+sy(Number(p.value)).toFixed(1)).join(' ');
						const zeroY=sy(0).toFixed(1);
						const spotX = Number(strategyRadarData?.spot || 0) >= minX && Number(strategyRadarData?.spot || 0) <= maxX ? sx(Number(strategyRadarData.spot)).toFixed(1) : null;
						const color = strategy.bias === 'bullish' ? '#16833b' : strategy.bias === 'bearish' ? '#c62828' : strategy.bias === 'volatility' ? '#7e57c2' : '#1565c0';
						const beLines=(strategy.breakevens||[]).map(be=>'<line x1="'+sx(Number(be)).toFixed(1)+'" y1="'+top+'" x2="'+sx(Number(be)).toFixed(1)+'" y2="'+(height-bottom)+'" stroke="#ff9800" stroke-dasharray="4 4"/><text x="'+sx(Number(be)).toFixed(1)+'" y="'+(height-7)+'" text-anchor="middle" font-size="10" fill="#ff9800">BE '+Number(be).toLocaleString(undefined,{maximumFractionDigits:0})+'</text>').join('');
						return '<svg class="strategy-payoff-svg" viewBox="0 0 '+width+' '+height+'" role="img" aria-label="Payoff at expiry">'
							+'<line x1="'+left+'" y1="'+zeroY+'" x2="'+(width-right)+'" y2="'+zeroY+'" stroke="#888" stroke-width="1"/>'
							+(spotX?'<line x1="'+spotX+'" y1="'+top+'" x2="'+spotX+'" y2="'+(height-bottom)+'" stroke="#2196f3" stroke-dasharray="3 4"/>':'')
							+beLines+'<polyline points="'+poly+'" fill="none" stroke="'+color+'" stroke-width="3"/>'
							+'<text x="'+left+'" y="14" font-size="11" fill="#777">P&amp;L at expiry (approx. USD)</text>'
							+'<text x="'+left+'" y="'+(height-7)+'" font-size="10" fill="#777">'+minX.toLocaleString(undefined,{maximumFractionDigits:0})+'</text>'
							+'<text x="'+(width-right)+'" y="'+(height-7)+'" text-anchor="end" font-size="10" fill="#777">'+maxX.toLocaleString(undefined,{maximumFractionDigits:0})+'</text>'
							+'<text x="4" y="'+(top+8)+'" font-size="10" fill="#777">'+radarMoney(maxY)+'</text>'
							+'<text x="4" y="'+(height-bottom)+'" font-size="10" fill="#777">'+radarMoney(minY)+'</text></svg>';
					}

					function renderStrategyRadarDetail(strategy) {
						const detail = document.getElementById('strategy-radar-detail');
						if (!detail) return;
						if (!strategy) { detail.innerHTML='<div class="strategy-note">No strategy matches the selected filters.</div>'; return; }
						const sourceLabel = strategy.source === 'confirmed_block' ? 'Confirmed Block' : 'Probable Screen Match';
						const legs=(strategy.legs||[]).map(leg=>'<div class="strategy-leg"><b>'+radarEsc(leg.label)+'</b><br/>Amount '+Number(leg.amount).toLocaleString()+' · Premium '+Number(leg.price).toFixed(5)+'</div>').join('');
						detail.innerHTML='<div class="strategy-title">'+radarEsc(strategy.name)+'</div>'
							+'<div class="strategy-meta"><span>Source</span><b>'+radarEsc(sourceLabel)+'</b><span>Horizon</span><b>'+radarEsc(strategy.horizon||'TERM')+'</b><span>Confidence</span><b>'+Number(strategy.confidence)+'%</b><span>Expiry</span><b>'+radarDate(strategy.expiry,false)+'</b><span>Detected</span><b>'+radarDate(strategy.entered_at,true)+'</b><span>Net premium</span><b>'+radarMoney(strategy.net_premium_usd)+'</b><span>Best in view</span><b>'+radarMoney(strategy.max_profit_in_view_usd)+'</b><span>Worst in view</span><b>'+radarMoney(strategy.max_loss_in_view_usd)+'</b></div>'
							+payoffSvg(strategy)+'<div style="margin-top:8px;font-weight:bold">Legs</div>'+legs
							+'<div class="strategy-note">Approximate USD-equivalent visualization. A Block ID confirms leg association, not the trader’s external hedge or spot position.</div>';
					}

					function filteredStrategyRadarRows() {
						const expiry = document.getElementById('strategy-radar-expiry')?.value || 'all';
						const source = document.getElementById('strategy-radar-source')?.value || 'all';
						return (strategyRadarData?.strategies || []).filter(row => (expiry === 'all' || row.expiry === expiry) && (source === 'all' || row.source === source));
					}

					function selectStrategyRadar(id) {
						selectedStrategyRadarId = id;
						renderStrategyRadar();
					}

					function renderStrategyRadar() {
						const rows = filteredStrategyRadarRows();
						if (!rows.some(row=>row.id===selectedStrategyRadarId)) selectedStrategyRadarId = rows[0]?.id || null;
						const list = document.getElementById('strategy-radar-list');
						if (list) {
							list.replaceChildren();
							rows.forEach(row => {
								const button=document.createElement('button'); button.type='button';
								button.className='strategy-card'+(row.id===selectedStrategyRadarId?' active':'');
								const badge=row.source==='confirmed_block'?'confirmed':'probable';
								button.innerHTML='<b>'+radarEsc(row.name)+'</b><br/><span class="'+badge+'">'+(badge==='confirmed'?'CONFIRMED BLOCK':'PROBABLE')+' · '+Number(row.confidence)+'%</span><br/><b>'+radarEsc(row.horizon||'TERM')+'</b> · '+radarDate(row.expiry,false);
								button.addEventListener('click',()=>selectStrategyRadar(row.id)); list.appendChild(button);
							});
						}
						const summary=document.getElementById('strategy-radar-summary');
						const totals=strategyRadarData?.summary||{};
						if (summary) summary.textContent=rows.length+' shown · '+Number(totals.confirmed_blocks||0)+' confirmed · '+Number(totals.probable_screen||0)+' probable · Bull '+Number(totals.bullish||0)+' / Bear '+Number(totals.bearish||0);
						renderStrategyRadarDetail(rows.find(row=>row.id===selectedStrategyRadarId));
					}

					async function refreshStrategyRadar() {
						if (!SHOW_STRATEGY_RADAR || MINIMAL_CHART) return;
						const response=await fetch(STRATEGY_RADAR_URL);
						if (!response.ok) throw new Error('Strategy Radar HTTP '+response.status);
						strategyRadarData=await response.json();
						if (!SHOW_STRATEGY_RADAR) return;
						const select=document.getElementById('strategy-radar-expiry');
						const previous=select?.value||'all';
						if (select) {
							select.innerHTML='<option value="all">All Expiries</option>';
							[...new Set((strategyRadarData.strategies||[]).map(row=>row.expiry))].sort().forEach(expiry=>{
								const match=(strategyRadarData.strategies||[]).find(row=>row.expiry===expiry);
								const option=document.createElement('option'); option.value=expiry; option.textContent=(match?.horizon||'TERM')+' · '+radarDate(expiry,false); select.appendChild(option);
							});
							select.value=[...select.options].some(option=>option.value===previous)?previous:'all';
						}
						renderStrategyRadar();
					}

					function closeStrategyRadar() {
						SHOW_STRATEGY_RADAR=false;
						const toggle=document.getElementById('strategy-radar-toggle'); if (toggle) toggle.checked=false;
						const panel=document.getElementById('strategy-radar-panel'); if (panel) panel.style.display='none';
					}

					function onToggleStrategyRadar() {
						SHOW_STRATEGY_RADAR=Boolean(document.getElementById('strategy-radar-toggle')?.checked);
						const panel=document.getElementById('strategy-radar-panel'); if (panel) panel.style.display=SHOW_STRATEGY_RADAR?'flex':'none';
						if (SHOW_STRATEGY_RADAR) safeRefresh('Strategy Radar', refreshStrategyRadar);
					}

					let SHOW_EXPIRY_PRICING = false;
					let expiryPricingData = null;
					let expiryTraceExpiriesLoaded = false;
					let SHOW_MM_HEDGE=false, mmHedgeData=null, mmHedgePriceLines=[], mmSelectedExpiries=new Set();
					let SHOW_EXPIRY_WAVE=false, expiryWaveData=null;
					const EXPIRY_PRICING_SNAPSHOT_KEY='dankbit_expiry_pricing_snapshots_'+ASSET;

					function expiryNumber(value, digits) {
						const number=Number(value);
						return Number.isFinite(number) ? number.toLocaleString(undefined,{maximumFractionDigits:digits == null ? 0 : digits}) : '—';
					}

					function expiryPrice(value) {
						const number=Number(value);
						return Number.isFinite(number) ? number.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2}) : '—';
					}

					function expiryPricingSvg(data) {
						const candles=[...(data.actual||[]),...(data.forecast||[])];
						if (!candles.length) return '<text x="380" y="150" text-anchor="middle" fill="#888">No candles available</text>';
						const levels=data.targets||{};
						const levelRows=[['BCG',Number(levels.bcg)],['BPG',Number(levels.bpg)],['SCG',Number(levels.scg)],['SPG',Number(levels.spg)]].filter(row=>Number.isFinite(row[1])).map(row=>{const s=expiryTraceLines[row[0]];return [row[0],row[1],s.color,s.style,s.width];});
						const values=candles.flatMap(c=>[Number(c.high),Number(c.low)]).concat(levelRows.map(row=>row[1])).filter(Number.isFinite);
						let min=Math.min(...values), max=Math.max(...values); const pad=Math.max((max-min)*0.08,Number(data.spot||1)*0.001); min-=pad; max+=pad;
						const width=760,height=300,left=64,right=138,top=17,bottom=34,plotW=width-left-right,plotH=height-top-bottom;
						const sy=value=>top+(max-value)/(max-min)*plotH;
						const slot=plotW/Math.max(candles.length,1), bodyW=Math.max(1.5,Math.min(12,slot*0.56));
						let svg='<rect width="760" height="300" fill="transparent"/>';
						for(let i=0;i<=4;i++){const y=top+i*plotH/4;const price=max-i*(max-min)/4;svg+='<line x1="'+left+'" y1="'+y+'" x2="'+(width-right)+'" y2="'+y+'" stroke="#888" stroke-opacity=".20"/><text x="4" y="'+(y+4)+'" font-size="11" font-weight="600" fill="#999">'+expiryNumber(price)+'</text>';}
						const labels=levelRows.map(row=>({row,lineY:sy(row[1]),labelY:sy(row[1])})).sort((a,b)=>a.labelY-b.labelY);
						for(let i=1;i<labels.length;i++) labels[i].labelY=Math.max(labels[i].labelY,labels[i-1].labelY+18);
						if(labels.length&&labels[labels.length-1].labelY>height-bottom){const shift=labels[labels.length-1].labelY-(height-bottom);labels.forEach(item=>item.labelY-=shift);}
						for(let i=labels.length-2;i>=0;i--) labels[i].labelY=Math.min(labels[i].labelY,labels[i+1].labelY-18);
						labels.forEach(item=>{const row=item.row,y=item.lineY,ly=item.labelY,dash=row[3]==='dotted'?'2 4':row[3]==='dashed'?'7 5':'';svg+='<line x1="'+left+'" y1="'+y+'" x2="'+(width-right)+'" y2="'+y+'" stroke="'+row[2]+'" stroke-width="'+row[4]+'"'+(dash?' stroke-dasharray="'+dash+'"':'')+'/><line x1="'+(width-right)+'" y1="'+y+'" x2="'+(width-right+7)+'" y2="'+ly+'" stroke="'+row[2]+'" stroke-width="'+row[4]+'"/><text x="'+(width-right+10)+'" y="'+(ly+4)+'" font-size="12.5" font-weight="700" fill="'+row[2]+'">'+row[0]+' '+expiryPrice(row[1])+'</text>';});
						const labelEvery=Math.max(1,Math.ceil(candles.length/6));
						candles.forEach((c,index)=>{const x=left+slot*(index+.5),open=sy(Number(c.open)),close=sy(Number(c.close)),high=sy(Number(c.high)),low=sy(Number(c.low));const up=Number(c.close)>=Number(c.open),forecast=c.kind==='forecast';const color=up?'#26a69a':'#ef5350';const opacity=forecast?Math.max(.24,.68-index*.004):.95;svg+='<line x1="'+x+'" y1="'+high+'" x2="'+x+'" y2="'+low+'" stroke="'+color+'" stroke-opacity="'+opacity+'"/><rect x="'+(x-bodyW/2)+'" y="'+Math.min(open,close)+'" width="'+bodyW+'" height="'+Math.max(1,Math.abs(close-open))+'" fill="'+color+'" fill-opacity="'+opacity+'"'+(forecast?' stroke="'+color+'" stroke-dasharray="2 2"':'')+'/>';if(index%labelEvery===0){const d=new Date(Number(c.time)*1000),day=String(d.getUTCDate()).padStart(2,'0'),hour=String(d.getUTCHours()).padStart(2,'0');svg+='<text x="'+x+'" y="'+(height-8)+'" text-anchor="middle" font-size="9.5" font-weight="600" fill="#999">'+day+' '+hour+':00</text>';}});
						const boundary=(data.actual||[]).length;if(boundary>0&&boundary<candles.length){const x=left+slot*boundary;svg+='<line x1="'+x+'" y1="'+top+'" x2="'+x+'" y2="'+(height-bottom)+'" stroke="#ff9800" stroke-width="1.5" stroke-dasharray="3 3"/><text x="'+(x+4)+'" y="'+(top+11)+'" font-size="9" fill="#ff9800">'+(data.mode==='explorer'?'AS OF':'NOW')+'</text>';}
						return svg;
					}

					function renderExpiryPricing() {
						const data=expiryPricingData, summary=document.getElementById('expiry-pricing-summary'), verdict=document.getElementById('expiry-trace-verdict'), flows=document.getElementById('expiry-pricing-flows'), svg=document.getElementById('expiry-pricing-svg');
						if (!data || !data.available) { if(summary)summary.textContent='No expiry data for this selection.'; if(flows)flows.replaceChildren(); if(svg)svg.innerHTML=''; return; }
						const generated=new Date(data.generated_at), next=new Date(generated.getTime()+900000);
						const liveTail=data.mode==='live'?' · next '+next.toLocaleTimeString('en-GB',{timeZone:'UTC',hour:'2-digit',minute:'2-digit'})+' UTC (<span id="expiry-pricing-countdown">—</span>)':'';
						if(summary) summary.innerHTML=(data.mode==='explorer'?'Explorer':'Live')+' · '+radarEsc(data.regime)+' · Adjusted Score '+(Number(data.direction_score)*100).toFixed(1)+' · Confidence '+Number(data.confidence)+'% · '+Number(data.hours_to_expiry).toFixed(1)+'h to expiry · '+radarEsc(data.interval)+' / '+Number(data.candle_count)+' bars'+liveTail;
						const u=data.unified_comment||{};if(verdict){const colors={CONTINUE:'#16833b',PIN:'#ef8c00',ROTATE:'#c62828'},color=colors[u.state]||'#777';verdict.style.borderColor=color;verdict.style.color=color;verdict.innerHTML=radarEsc((u.state||'—')+' '+(u.direction||'')+' '+(u.preposition||'near')+' '+(u.level||'')+' '+expiryPrice(u.price))+'<small>'+radarEsc('Confidence '+Number(u.confidence||0)+'% · '+(u.reason||''))+'</small>';}
						if(flows){const flowKeys=['BC','BP','SC','SP'],totalAdjusted=flowKeys.reduce((sum,key)=>sum+Number(data.adjusted_flow?.[key]||0),0);flows.innerHTML=flowKeys.map(key=>{const labels={BC:'Buyer Call',BP:'Buyer Put',SC:'Seller Call',SP:'Seller Put'},m=data.group_metrics?.[key]||{},contracts=Number(data.contracts?.[key]||0),adjusted=Number(data.adjusted_flow?.[key]||0),remaining=Number(data.remaining_pressure?.[key]||0),impactShare=totalAdjusted>0?100*adjusted/totalAdjusted:0,remainingPct=adjusted>0?100*remaining/adjusted:0;const tip='Internal State: '+(m.state||'—')+' | Time Viability: '+expiryNumber(Number(m.time_viability)*100,1)+'% | Theta Erosion: '+expiryNumber(Number(m.theta_erosion)*100,1)+'% | IV Adjustment: '+expiryNumber(m.iv_adjustment,3)+' | Vega Exposure: '+expiryNumber(m.vega_exposure,2)+' | Already Priced: '+expiryNumber(Number(m.directional_completion)*100,1)+'%';return '<div class="expiry-flow-card" title="'+radarEsc(tip)+'"><b>'+labels[key]+'</b>'+expiryNumber(contracts,2)+' contracts<br/>Impact '+expiryNumber(impactShare,1)+'%<br/>Remaining '+expiryNumber(remainingPct,1)+'%</div>';}).join('');}
						if(svg) svg.innerHTML=expiryPricingSvg(data);
						updateExpiryPricingCountdown();
					}

					function storeExpiryPricingSnapshot(data){
						try{
							const bucket=Math.floor(new Date(data.generated_at).getTime()/900000);
							let rows=JSON.parse(localStorage.getItem(EXPIRY_PRICING_SNAPSHOT_KEY)||'[]');
							if(!Array.isArray(rows)) rows=[];
							if(!rows.some(row=>row.bucket===bucket)) rows.push({bucket,generated_at:data.generated_at,expiry:data.expiry,spot:data.spot,regime:data.regime,direction_score:data.direction_score,confidence:data.confidence,targets:data.targets,forecast:data.forecast});
							localStorage.setItem(EXPIRY_PRICING_SNAPSHOT_KEY,JSON.stringify(rows.slice(-192)));
						}catch(e){console.warn('Expiry Trace snapshot unavailable',e);}
					}

					function updateExpiryPricingCountdown(){
						const node=document.getElementById('expiry-pricing-countdown');if(!node||!expiryPricingData?.generated_at)return;
						const seconds=Math.max(0,Math.ceil((new Date(expiryPricingData.generated_at).getTime()+900000-Date.now())/1000));
						node.textContent=String(Math.floor(seconds/60)).padStart(2,'0')+':'+String(seconds%60).padStart(2,'0');
					}

					function expiryLocalValue(value){const d=new Date(value);return Number.isFinite(d.getTime())?d.toISOString().slice(0,16):'';}
					async function loadExpiryTraceExpiries(){
						if(expiryTraceExpiriesLoaded)return;
						const response=await fetch(EXPIRY_TRACE_EXPIRIES_URL);if(!response.ok)throw new Error('Expiry Trace expiries HTTP '+response.status);
						const data=await response.json(),select=document.getElementById('expiry-trace-expiry');
						if(select){select.innerHTML=(data.expiries||[]).map(x=>'<option value="'+radarEsc(x)+'">'+radarEsc(new Date(x).toLocaleString('en-GB',{timeZone:'UTC',dateStyle:'medium',timeStyle:'short'}))+' UTC</option>').join('');if(select.options.length)select.selectedIndex=select.options.length-1;}
						expiryTraceExpiriesLoaded=true;
					}
					function onExpiryTraceMode(){
						const explorer=document.getElementById('expiry-trace-mode')?.value==='explorer';
						['expiry-trace-expiry','expiry-trace-from','expiry-trace-asof','expiry-trace-interval','expiry-trace-candles','expiry-trace-apply'].forEach(id=>{const n=document.getElementById(id);if(n)n.disabled=!explorer;});
						if(explorer){loadExpiryTraceExpiries().then(()=>{const now=new Date();document.getElementById('expiry-trace-asof').value=expiryLocalValue(now);document.getElementById('expiry-trace-from').value=expiryLocalValue(new Date(now.getTime()-86400000));}).catch(e=>console.warn(e));}
						else safeRefresh('Expiry Trace',refreshExpiryPricing);
					}
					function expiryTraceUrl(){
						if(document.getElementById('expiry-trace-mode')?.value!=='explorer')return EXPIRY_PRICING_URL+'?mode=live';
						const q=new URLSearchParams({mode:'explorer',expiry:document.getElementById('expiry-trace-expiry').value,trade_from:new Date(document.getElementById('expiry-trace-from').value).toISOString(),as_of:new Date(document.getElementById('expiry-trace-asof').value).toISOString(),interval:document.getElementById('expiry-trace-interval').value,candles:document.getElementById('expiry-trace-candles').value});
						return EXPIRY_PRICING_URL+'?'+q.toString();
					}
					function applyExpiryTrace(){safeRefresh('Expiry Trace',refreshExpiryPricing);}

					async function refreshExpiryPricing() {
