					function expiryWaveEscape(value){return String(value==null?'':value).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));}
					function expiryWaveNumber(value,digits){const n=Number(value);return Number.isFinite(n)?n.toLocaleString(undefined,{minimumFractionDigits:0,maximumFractionDigits:digits==null?0:digits}):'—';}
					function expiryWaveSigned(value,digits){const n=Number(value);return Number.isFinite(n)?(n>=0?'+':'−')+expiryWaveNumber(Math.abs(n),digits):'—';}
					function expiryWaveDate(value,year){return value?new Date(value).toLocaleDateString('en-GB',{timeZone:'UTC',day:'2-digit',month:'short',...(year?{year:'2-digit'}:{})}).toUpperCase():'—';}
					function expiryWavePath(points){
						if(!points||points.length<2)return points?.length?'M '+points[0].x+' '+points[0].y:'';
						const slopes=[];for(let i=0;i<points.length-1;i++){const dx=Math.max(1e-6,points[i+1].x-points[i].x);slopes.push((points[i+1].y-points[i].y)/dx);}
						const tangent=new Array(points.length);tangent[0]=slopes[0];tangent[points.length-1]=slopes[slopes.length-1];
						for(let i=1;i<points.length-1;i++){const a=slopes[i-1],b=slopes[i];tangent[i]=a*b<=0?0:(2*a*b)/(a+b);}
						let d='M '+points[0].x.toFixed(2)+' '+points[0].y.toFixed(2);
						for(let i=0;i<points.length-1;i++){const p=points[i],q=points[i+1],dx=q.x-p.x,s=slopes[i];let m0=tangent[i],m1=tangent[i+1];if(Math.abs(s)<1e-9){m0=0;m1=0;}else{const a=m0/s,b=m1/s,norm=a*a+b*b;if(norm>9){const factor=3/Math.sqrt(norm);m0=factor*a*s;m1=factor*b*s;}}const c1x=p.x+dx/3,c2x=q.x-dx/3,c1y=p.y+m0*dx/3,c2y=q.y-m1*dx/3;d+=' C '+c1x.toFixed(2)+' '+c1y.toFixed(2)+' '+c2x.toFixed(2)+' '+c2y.toFixed(2)+' '+q.x.toFixed(2)+' '+q.y.toFixed(2);}
