					}
					function expiryWaveRgb(hex){const h=String(hex||'#26a69a').replace('#','');return 'rgb('+parseInt(h.slice(0,2),16)+','+parseInt(h.slice(2,4),16)+','+parseInt(h.slice(4,6),16)+')';}
					function renderExpiryWave(){
						const data=expiryWaveData,svg=document.getElementById('expiry-wave-svg'),summary=document.getElementById('expiry-wave-summary'),list=document.getElementById('expiry-wave-nodes');if(!svg||!summary||!list)return;
						if(!data?.available||!Number.isFinite(Number(data.spot))||!(data.nodes||[]).length){summary.textContent='No weekly or monthly expiry nodes with usable options data were found.';svg.innerHTML='';list.replaceChildren();return;}
						const source=data.nodes.slice().sort((a,b)=>new Date(a.expiry)-new Date(b.expiry)),nowMs=new Date(data.generated_at).getTime(),spot=Number(data.spot);
						const points=[{time:nowMs,price:spot,range_low:spot,range_high:spot,kind:'NOW',expiry:data.generated_at},...source.map(n=>({time:new Date(n.expiry).getTime(),price:Number(n.price),range_low:Number(n.range_low),range_high:Number(n.range_high),kind:n.kind,expiry:n.expiry,node:n}))].filter(p=>Number.isFinite(p.time)&&Number.isFinite(p.price));
						if(points.length<2){summary.textContent='Not enough valid expiry data to draw the scenario path.';svg.innerHTML='';list.replaceChildren();return;}
						const W=1000,H=420,L=78,R=22,T=24,B=48,x0=points[0].time,x1=Math.max(points[points.length-1].time,x0+86400000);let minP=Math.min(...points.map(p=>p.range_low)),maxP=Math.max(...points.map(p=>p.range_high));const pad=Math.max((maxP-minP)*0.08,spot*0.015,1);minP=Math.max(0,minP-pad);maxP+=pad;if(maxP<=minP)maxP=minP+1;
						const X=t=>L+(t-x0)/(x1-x0)*(W-L-R),Y=p=>T+(maxP-p)/(maxP-minP)*(H-T-B),main=points.map(p=>({x:X(p.time),y:Y(p.price)})),upper=points.map(p=>({x:X(p.time),y:Y(p.range_high)})),lower=points.map(p=>({x:X(p.time),y:Y(p.range_low)}));
						const color=expiryWaveSettings.pathColor,rangeColor=expiryWaveSettings.rangeColor,strokeDash=expiryWaveSettings.pathStyle==='dashed'?'10 6':expiryWaveSettings.pathStyle==='dotted'?'2 5':'none';
						let markup='';for(let i=0;i<=4;i++){const price=minP+(maxP-minP)*i/4,y=Y(price);markup+='<line class="ew-grid" x1="'+L+'" y1="'+y.toFixed(2)+'" x2="'+(W-R)+'" y2="'+y.toFixed(2)+'"/><text x="'+(L-8)+'" y="'+(y+4).toFixed(2)+'" text-anchor="end">'+expiryWaveNumber(price)+'</text>';}
						for(let i=0;i<=5;i++){const time=x0+(x1-x0)*i/5,x=X(time),label=new Date(time).toLocaleDateString('en-GB',{timeZone:'UTC',day:'2-digit',month:'short'}).toUpperCase();markup+='<line class="ew-grid" x1="'+x.toFixed(2)+'" y1="'+T+'" x2="'+x.toFixed(2)+'" y2="'+(H-B)+'"/><text x="'+x.toFixed(2)+'" y="'+(H-15)+'" text-anchor="middle">'+label+'</text>';}
						const bandUpper=expiryWavePath(upper),bandLower=expiryWavePath(lower.slice().reverse()),lowerTail=bandLower.replace(/^M[^C]*/,'');const bandPath=bandUpper+' L '+lower[lower.length-1].x.toFixed(2)+' '+lower[lower.length-1].y.toFixed(2)+' '+lowerTail+' Z';
						if(expiryWaveSettings.showRange)markup+='<path d="'+bandPath+'" fill="'+rangeColor+'" fill-opacity=".16" stroke="none"/>';
						const path=expiryWavePath(main);markup+='<path d="'+path+'" fill="none" stroke="'+color+'" stroke-width="'+expiryWaveSettings.pathWidth+'" stroke-linecap="round" stroke-linejoin="round"'+(strokeDash!=='none'?' stroke-dasharray="'+strokeDash+'"':'')+'/>';
						const nowX=X(nowMs);markup+='<line class="ew-now" x1="'+nowX.toFixed(2)+'" y1="'+T+'" x2="'+nowX.toFixed(2)+'" y2="'+(H-B)+'"/><text x="'+Math.min(nowX+5,W-R-25).toFixed(2)+'" y="'+(T+13)+'" fill="#ef8c00">NOW</text>';
						points.slice(1).forEach((p,i)=>{const x=X(p.time),y=Y(p.price),n=p.node,tag=n.kind==='YE'?'YE':n.kind;const tip=tag+' '+expiryWaveDate(n.expiry,true)+' · Gamma '+expiryWaveNumber(n.price,2)+' · Δ '+expiryWaveSigned(Number(n.delta_bias)*100,1)+'% · Θ/day '+expiryWaveSigned(n.theta_per_day,2)+' · Vega/IV pt '+expiryWaveSigned(n.vega_per_iv_point,2)+' · IV '+expiryWaveNumber(n.iv_percent,2)+'% · trades '+expiryWaveNumber(n.trade_count);markup+='<circle cx="'+x.toFixed(2)+'" cy="'+y.toFixed(2)+'" r="4.5" fill="'+color+'" stroke="#fff" stroke-width="1.5"><title>'+expiryWaveEscape(tip)+'</title></circle>';if(expiryWaveSettings.showLabels){const label=tag+' '+expiryWaveDate(n.expiry,false);markup+='<text class="ew-node-label" x="'+x.toFixed(2)+'" y="'+Math.max(T+16,y-10).toFixed(2)+'" text-anchor="middle" fill="'+color+'">'+expiryWaveEscape(label)+'</text>';}});
						markup+='<circle cx="'+X(nowMs).toFixed(2)+'" cy="'+Y(spot).toFixed(2)+'" r="4" fill="#ef8c00"/>';
						svg.innerHTML=markup;
						const earliest=source.map(n=>n.first_seen).filter(Boolean).sort()[0],date=earliest?expiryWaveDate(earliest,true):'—',updated=new Date(data.generated_at).toLocaleTimeString('en-GB',{timeZone:'UTC',hour:'2-digit',minute:'2-digit'});
						summary.textContent=source.length+' expiry nodes · '+expiryWaveNumber(data.trade_count)+' trades · history from '+date+' · spot '+expiryWaveNumber(spot,2)+' · updated '+updated+' UTC';
						const kindColor={W:'#7e57c2',M:'#00838f',YE:'#c62828'};
						list.innerHTML=source.map(n=>{const delta=Number(n.delta_bias)*100;const first=n.first_seen?expiryWaveDate(n.first_seen,true):'—';return '<div class="expiry-wave-node" style="border-left-color:'+(kindColor[n.kind]||'#00838f')+'"><b>'+expiryWaveEscape(n.kind)+' · '+expiryWaveEscape(expiryWaveDate(n.expiry,true))+'</b><strong>'+expiryWaveNumber(n.price,2)+'</strong><small>Δ lean '+expiryWaveSigned(delta,1)+'% · Θ/day '+expiryWaveSigned(n.theta_per_day,2)+' · Vega/IV pt '+expiryWaveSigned(n.vega_per_iv_point,2)+' · IV '+expiryWaveNumber(n.iv_percent,2)+'% · '+expiryWaveNumber(n.trade_count)+' trades · first '+expiryWaveEscape(first)+' · Θ retention '+expiryWaveNumber(n.theta_retention_percent,1)+'%</small></div>';}).join('');
					}
					async function refreshExpiryWave(){if(!SHOW_EXPIRY_WAVE||MINIMAL_CHART)return;const response=await fetch(EXPIRY_WAVE_URL);if(!response.ok)throw new Error('Expiry Wave HTTP '+response.status);expiryWaveData=await response.json();if(SHOW_EXPIRY_WAVE)renderExpiryWave();}
					function onToggleExpiryWave(){SHOW_EXPIRY_WAVE=Boolean(document.getElementById('expiry-wave-toggle')?.checked);const panel=document.getElementById('expiry-wave-panel');if(panel)panel.style.display=SHOW_EXPIRY_WAVE?'flex':'none';if(SHOW_EXPIRY_WAVE)safeRefresh('Expiry Wave',refreshExpiryWave);}
					function closeExpiryWave(){SHOW_EXPIRY_WAVE=false;const toggle=document.getElementById('expiry-wave-toggle');if(toggle)toggle.checked=false;const panel=document.getElementById('expiry-wave-panel');if(panel)panel.style.display='none';}
					function toggleExpiryWaveSettings(){const settings=document.getElementById('expiry-wave-settings');if(!settings)return;const show=settings.style.display!=='grid';settings.style.display=show?'grid':'none';if(show){document.getElementById('ew-path-color').value=expiryWaveSettings.pathColor;document.getElementById('ew-range-color').value=expiryWaveSettings.rangeColor;document.getElementById('ew-path-style').value=expiryWaveSettings.pathStyle;document.getElementById('ew-path-width').value=expiryWaveSettings.pathWidth;document.getElementById('ew-show-range').checked=expiryWaveSettings.showRange;document.getElementById('ew-show-labels').checked=expiryWaveSettings.showLabels;}}
					function saveExpiryWaveSettings(){const pathColor=document.getElementById('ew-path-color')?.value||expiryWaveSettings.pathColor,rangeColor=document.getElementById('ew-range-color')?.value||expiryWaveSettings.rangeColor,style=document.getElementById('ew-path-style')?.value,width=parseInt(document.getElementById('ew-path-width')?.value,10);expiryWaveSettings={pathColor:/^#[0-9a-f]{6}$/i.test(pathColor)?pathColor:DEFAULT_EXPIRY_WAVE_SETTINGS.pathColor,rangeColor:/^#[0-9a-f]{6}$/i.test(rangeColor)?rangeColor:DEFAULT_EXPIRY_WAVE_SETTINGS.rangeColor,pathStyle:['solid','dashed','dotted'].includes(style)?style:'solid',pathWidth:Math.max(1,Math.min(5,Number.isFinite(width)?width:3)),showRange:Boolean(document.getElementById('ew-show-range')?.checked),showLabels:Boolean(document.getElementById('ew-show-labels')?.checked)};localStorage.setItem(EXPIRY_WAVE_SETTINGS_KEY,JSON.stringify(expiryWaveSettings));if(SHOW_EXPIRY_WAVE&&expiryWaveData)renderExpiryWave();}

					let nearestExpiryStr = null;
					let lastTradeCount = 0;
					let lastTradeTs = null;
					// Set from /api/zones-box's echoed `window_hours` while the
					// Option Flow dropdown is on "Auto (Time to Expiry)" — null
					// otherwise (every non-auto mode). Shown in the footer so the
					// user sees what the server-side _auto_window_hours() picked,
					// matching /4l/<asset>'s own "Auto → <N>h/<N>d" footer text.
					let zonesBoxAutoHours = null;
					function zonesBoxHoursLabel(hours) {
						return (hours >= 24 && hours % 24 === 0) ? (hours / 24) + 'd' : hours + 'h';
					}

					// Shown in real UTC (not the browser-local tzOffset shift the
					// chart's own time axis uses) — this is a staleness check
					// against server time, not a chart position, so genuine UTC
					// is what's directly comparable to "now" when eyeballing
					// whether dankbit_ws has stalled (see refreshLastTrade).
					function formatLastTradeTs(iso) {
						if (!iso) return null;
						return new Date(iso).toLocaleString('de-DE', {
							timeZone: 'UTC',
							year: 'numeric', month: '2-digit', day: '2-digit',
							hour: '2-digit', minute: '2-digit', second: '2-digit',
						}) + ' UTC';
					}

					function updateStatusLine() {
						const expiries = [INSTRUMENT, MONTHLY_INST].filter(Boolean).join('  ·  ');
						let text = expiries + '  ·  ' + lastTradeCount + ' trades';
						if (nearestExpiryStr) text += '  ·  Nearest: ' + nearestExpiryStr;
						if (zonesBoxAutoHours !== null) {
							text += '  ·  Option Flow: Auto → ' + zonesBoxHoursLabel(zonesBoxAutoHours) + ' trailing window';
						}
						const lastTradeLabel = formatLastTradeTs(lastTradeTs);
						if (lastTradeLabel) text += '  ·  Last trade: ' + lastTradeLabel;
						setStatus(text);
					}

					async function refreshNearestExpiry() {
						// Cheap standalone lookup (no curve-building) — the yellow zones
						// boxes use this same nearest-active-expiry internally, but via
						// their own full computation, not this lightweight endpoint.
						const data = await (await fetch(NEAREST_EXPIRY_URL)).json();
						nearestExpiryStr = data.expiry || null;
						updateStatusLine();
					}

					async function refreshLastTrade() {
						// Cheap standalone lookup (no curve-building), asset-wide (not
						// restricted to any one expiry) — a growing gap between this
						// and "now" is the at-a-glance signal that dankbit_ws has
						// stalled (its DB connection can die without crashing the
						// container, silently dropping every trade).
						const data = await (await fetch(LAST_TRADE_URL)).json();
						lastTradeTs = data.last_trade_ts || null;
						if (!SHOW_GAMMA_HORIZON) lastTradeCount = Number(data.active_trade_count || 0);
						updateStatusLine();
					}

					// Populated by refreshBands() from Smart Liquidity rows only.
					// They are used to place optional hourly Smart Liquidity dominance dots.
					let smartLiqUpperPoints = [];
					let smartLiqLowerPoints = [];
					let smartLiqTermState = [];
					let smartLiqMarkerLayer = null;
					let smartLiqMarkerObserversInstalled = false;

					function clearSmartLiqTermMarkers() {
						smartLiqTermState = [];
						if (smartLiqMarkerLayer) smartLiqMarkerLayer.replaceChildren();
					}

					function clearBandOnlyLines() {
						bandUpperSeries.setData([]);
						bandLowerSeries.setData([]);
						bandUpperProvisionalSeries.setData([]);
						bandLowerProvisionalSeries.setData([]);
						bandUpperSeries.setMarkers([]);
						bandLowerSeries.setMarkers([]);
						bandUpperProvisionalSeries.setMarkers([]);
						bandLowerProvisionalSeries.setMarkers([]);
						gammaBandSeries.setData([]);
					}

					function clearSmartLiquidityLines() {
						smartLiqUpperSeries.setData([]);
						smartLiqLowerSeries.setData([]);
						smartLiqUpperSeries.setMarkers([]);
						smartLiqLowerSeries.setMarkers([]);
						smartLiqUpperPoints = [];
						smartLiqLowerPoints = [];
						clearSmartLiqTermMarkers();
						liveBandUpperSeries.setData([]);
						liveBandLowerSeries.setData([]);
						liveBandUpperSeries.setMarkers([]);
						liveBandLowerSeries.setMarkers([]);
					}

					function clearBandsLines() {
						clearBandOnlyLines();
						clearSmartLiquidityLines();
					}

					// Value of a sparse, time-sorted {time, value} line at an
					// arbitrary time, linearly interpolated between its two
					// bracketing points. Clamped to the first/last value when
					// time falls outside the line's own range.
					function interpolateOnLine(points, time) {
						if (!points.length) return null;
						if (time <= points[0].time) return points[0].value;
						if (time >= points[points.length - 1].time) return points[points.length - 1].value;
						for (let i = 0; i < points.length - 1; i++) {
							const a = points[i], b = points[i + 1];
							if (time >= a.time && time <= b.time) {
								const frac = (time - a.time) / (b.time - a.time);
								return a.value + frac * (b.value - a.value);
							}
						}
						return points[points.length - 1].value;
					}

					function mergeSmartLiqPoints(historyPoints, termPoints) {
						const merged = new Map();
						(historyPoints || []).forEach(p => merged.set(p.time, { time: p.time, value: p.value }));
						(termPoints || []).forEach(p => merged.set(p.time, { time: p.time, value: p.value }));
						return Array.from(merged.values()).sort((a, b) => a.time - b.time);
					}

					function percentile(values, q) {
						if (!values.length) return 0;
						const sorted = values.slice().sort((a, b) => a - b);
						const pos = (sorted.length - 1) * q;
						const base = Math.floor(pos), rest = pos - base;
						return sorted[base + 1] !== undefined
							? sorted[base] + rest * (sorted[base + 1] - sorted[base])
							: sorted[base];
					}

					function recentAtr() {
						if (realCandles.length < 2) return 0;
						const sample = realCandles.slice(-15);
						const ranges = [];
						for (let i = 1; i < sample.length; i++) {
							const c = sample[i], prev = sample[i - 1];
							ranges.push(Math.max(c.high - c.low, Math.abs(c.high - prev.close), Math.abs(c.low - prev.close)));
						}
						return ranges.length ? ranges.reduce((a, b) => a + b, 0) / ranges.length : 0;
					}

					function recentBandTrend(atr) {
						if (!atr || realCandles.length < 8) return 0;
						const sample = realCandles.slice(-8);
						const move = Number(sample[sample.length - 1].close) - Number(sample[0].close);
						return move > 0.35 * atr ? 1 : move < -0.35 * atr ? -1 : 0;
					}

					function adaptiveBandBuffers(rawUpper, rawLower) {
						if (!realCandles.length || rawUpper.length < 2 || rawLower.length < 2) return { upper: 0, lower: 0 };
						const newest = realCandles[realCandles.length - 1].time;
						const cutoff = newest - 30 * 86400;
						const firstTime = Math.max(rawUpper[0].time, rawLower[0].time);
						const lastTime = Math.min(rawUpper[rawUpper.length - 1].time, rawLower[rawLower.length - 1].time);
						const upperExcursions = [], lowerExcursions = [];
						realCandles.forEach(c => {
							if (c.time < cutoff || c.time < firstTime || c.time > lastTime) return;
							const upper = interpolateOnLine(rawUpper, c.time);
							const lower = interpolateOnLine(rawLower, c.time);
							if (upper === null || lower === null || upper <= lower) return;
							const halfWidth = (upper - lower) / 2;
							// Only wick excursions that close back inside are reactions.
							// Accepted closes outside are breakouts and never widen the band.
							if (c.high > upper && c.close <= upper) upperExcursions.push(Math.min(c.high - upper, halfWidth));
							if (c.low < lower && c.close >= lower) lowerExcursions.push(Math.min(lower - c.low, halfWidth));
						});
						return {
							upper: upperExcursions.length >= 5 ? percentile(upperExcursions, 0.80) : 0,
							lower: lowerExcursions.length >= 5 ? percentile(lowerExcursions, 0.80) : 0,
						};
					}

					function densifyBandAnchors(anchors, field) {
						if (anchors.length < 2) return anchors.map(p => ({ time: p.time, value: p[field] }));
						const dense = [];
						for (let i = 0; i < anchors.length - 1; i++) {
							const a = anchors[i], b = anchors[i + 1];
							const displayStep = INTERVAL_SECONDS[INTERVAL] || 3600;
							const steps = Math.max(1, Math.round((b.time - a.time) / displayStep));
							for (let step = 0; step < steps; step++) {
								const x = step / steps;
								const eased = x * x * (3 - 2 * x); // continuous slope at each expiry anchor
								dense.push({ time: Math.round(a.time + step * (b.time - a.time) / steps), value: a[field] + eased * (b[field] - a[field]) });
							}
						}
						const last = anchors[anchors.length - 1];
						dense.push({ time: last.time, value: last[field] });
						return dense;
					}

					function isRenderableBandRow(r) {
						const upper = Number(r && r.high_resistance);
						const lower = Number(r && r.low_support);
						return Number.isFinite(upper) && Number.isFinite(lower) && upper > 0 && lower > 0 && upper > lower;
					}

					function buildAdaptiveBands(rows, stateScope, startAnchor) {
						const anchors = rows.filter(isRenderableBandRow)
							.map(r => ({
								time: Math.floor(r.t / 1000) + tzOffset,
								rawUpper: Number(r.high_resistance), rawLower: Number(r.low_support),
								expiryIndex: r.expiry_index == null ? null : Number(r.expiry_index),
								qualityStatus: r.quality_status || 'valid',
							})).sort((a, b) => a.time - b.time);
						if (!bandAdaptiveSmoothing || !anchors.length) return {
							upper: anchors.map(p => ({ time: p.time, value: p.rawUpper })),
							lower: anchors.map(p => ({ time: p.time, value: p.rawLower })),
						};

						// Confirmed and provisional paths must not update the same
						// smoothing memory.  The bridge contains the final confirmed
						// point and otherwise caused that anchor to be smoothed twice.
						// v3 intentionally retires the older, over-wide width memory.
						const stateKey = 'v3:' + INTERVAL + ':' + (stateScope || 'confirmed');
						const timeframeState = bandSmoothingState[stateKey] || {};
						bandSmoothingState[stateKey] = timeframeState;
						const rawUpper = anchors.map(p => ({ time: p.time, value: p.rawUpper }));
						const rawLower = anchors.map(p => ({ time: p.time, value: p.rawLower }));
						const buffers = adaptiveBandBuffers(rawUpper, rawLower);
						const atr = recentAtr();
						const trend = recentBandTrend(atr);
						const latestPrice = realCandles.length ? Number(realCandles[realCandles.length - 1].close) : 0;
						const expiryWeights = { 0: 0.50, 1: 0.30, 2: 0.20 };
						const termAnchors = anchors.filter(p => p.expiryIndex !== null);
						const weightedQuality = termAnchors.reduce((sum, p) => sum + (expiryWeights[p.expiryIndex] || 0) * (p.qualityStatus === 'low' ? 0.25 : 1.0), 0);
						const presentWeight = termAnchors.reduce((sum, p) => sum + (expiryWeights[p.expiryIndex] || 0), 0);
						const qualityCoverage = presentWeight > 0 ? weightedQuality / presentWeight : 1.0;
						// Preserve raw intersections. Only the extra overshoot expansion
						// is reduced by 25-35%, depending on T1/T2/T3 data quality.
						const expansionScale = 0.65 + 0.10 * qualityCoverage;
						const targetUpperBuffer = buffers.upper * expansionScale;
						const targetLowerBuffer = buffers.lower * expansionScale;
						const strongAnchorCount = termAnchors.filter(p => p.qualityStatus !== 'low').length;
						const liveKeys = new Set();

						anchors.forEach((p, anchorIndex) => {
							const key = String(p.time - tzOffset);
							liveKeys.add(key);
							const rawCenter = (p.rawUpper + p.rawLower) / 2;
							const rawHalfWidth = Math.max(0, (p.rawUpper - p.rawLower) / 2);
							if (anchorIndex === 0 && startAnchor && Number(startAnchor.time) === Number(p.time)) {
								// The dashed route must start at the exact rendered end of
								// the confirmed route. Do not smooth/buffer this bridge twice.
								p.upper = Number(startAnchor.upper);
								p.lower = Number(startAnchor.lower);
								timeframeState[key] = {
									center: (p.upper + p.lower) / 2,
									halfWidth: (p.upper - p.lower) / 2,
									upperBuffer: 0, lowerBuffer: 0, rawCenter, updatedAt: Date.now(),
								};
								return;
							}
							const prev = timeframeState[key];
							let alphaCenter = 0.30, alphaWidth = 0.20;
							if (prev && atr > 0) {
								const activity = Math.abs(rawCenter - Number(prev.rawCenter || rawCenter)) / atr;
								if (activity < 0.20) { alphaCenter = 0.20; alphaWidth = 0.12; }
								else if (activity > 0.75) { alphaCenter = 0.45; alphaWidth = 0.30; }
							}
							// Width contracts faster than it expands. This removes the long
							// memory of an obsolete opposite band without changing Center.
							if (prev && rawHalfWidth < Number(prev.halfWidth)) alphaWidth = Math.max(alphaWidth, 0.34);
							let center = prev ? Number(prev.center) + alphaCenter * (rawCenter - Number(prev.center)) : rawCenter;
							let halfWidth = prev ? Number(prev.halfWidth) + alphaWidth * (rawHalfWidth - Number(prev.halfWidth)) : rawHalfWidth;
							let upperBuffer = prev ? Number(prev.upperBuffer || 0) + alphaWidth * (targetUpperBuffer - Number(prev.upperBuffer || 0)) : targetUpperBuffer;
							let lowerBuffer = prev ? Number(prev.lowerBuffer || 0) + alphaWidth * (targetLowerBuffer - Number(prev.lowerBuffer || 0)) : targetLowerBuffer;
							if (prev && atr > 0) {
								const centerCap = 0.30 * atr;
								const widthCap = rawHalfWidth < Number(prev.halfWidth) ? 0.30 * atr : 0.15 * atr;
								center = Math.max(Number(prev.center) - centerCap, Math.min(Number(prev.center) + centerCap, center));
								halfWidth = Math.max(Number(prev.halfWidth) - widthCap, Math.min(Number(prev.halfWidth) + widthCap, halfWidth));
							}
							// A low-quality T3 may shape direction, but cannot hold the whole
							// channel open by itself.
							if (stateScope === 'provisional' && p.expiryIndex === 2 && p.qualityStatus === 'low' && termAnchors.length) {
								const weightedHalfWidth = termAnchors.reduce((sum, a) => {
									const weight = (expiryWeights[a.expiryIndex] || 0) * (a.qualityStatus === 'low' ? 0.25 : 1.0);
									return sum + weight * Math.max((a.rawUpper - a.rawLower) / 2, 0);
								}, 0) / Math.max(weightedQuality, 1e-9);
								halfWidth = Math.min(halfWidth, Math.max(0.25 * atr, 1.10 * weightedHalfWidth));
							}
							p.upper = center + halfWidth + upperBuffer;
							p.lower = center - halfWidth - lowerBuffer;
							// Asymmetric regime control: retain the trend-side band and bring
							// only the stale opposite band closer. More than 4 ATR requires
							// at least two sound expiry anchors.
							if (stateScope === 'provisional' && atr > 0 && latestPrice > 0) {
								const opposingAtrCap = (strongAnchorCount >= 2 ? 4.25 : 3.50) * atr;
								if (trend < 0) p.upper = Math.min(p.upper, latestPrice + opposingAtrCap);
								else if (trend > 0) p.lower = Math.max(p.lower, latestPrice - opposingAtrCap);
								if (p.upper <= p.lower) {
									const minimumHalfWidth = Math.max(0.25 * atr, rawHalfWidth * 0.50);
									p.upper = center + minimumHalfWidth;
									p.lower = center - minimumHalfWidth;
								}
							}
							timeframeState[key] = { center, halfWidth, upperBuffer, lowerBuffer, rawCenter, updatedAt: Date.now() };
						});
						Object.keys(timeframeState).forEach(key => {
							if (!liveKeys.has(key) && Date.now() - Number(timeframeState[key].updatedAt || 0) > 35 * 86400000) delete timeframeState[key];
						});
						try { localStorage.setItem(BAND_SMOOTHING_STATE_KEY, JSON.stringify(bandSmoothingState)); } catch (e) { /* storage quota: chart still works */ }
						return { upper: densifyBandAnchors(anchors, 'upper'), lower: densifyBandAnchors(anchors, 'lower') };
					}

					async function refreshBands() {
						if (MINIMAL_CHART || (!SHOW_BANDS && !SHOW_SMART_LIQUIDITY)) return;
						const response = await fetch(withOptionFlowWindow(BANDS_URL));
						if (!response.ok) throw new Error('Bands HTTP ' + response.status);
						const data = await response.json();
						if (data.error) throw new Error('Bands: ' + data.error);
						if (!SHOW_BANDS && !SHOW_SMART_LIQUIDITY) return;
						const rows = data.bands || [];

						if (SHOW_BANDS) {
							const confirmedRows = rows.filter(r => r.confirmation_status !== 'provisional');
							const provisionalRows = rows.filter(r => r.confirmation_status === 'provisional')
								.sort((a, b) => Number(a.t) - Number(b.t));
							gammaBandSeries.setData(rows.filter(r => Number(r.gamma_band) > 0).map(r => ({ time: Math.floor(r.t / 1000) + tzOffset, value: Number(r.gamma_band) })));
							const confirmedValidRows = confirmedRows.filter(isRenderableBandRow);
							const confirmedBands = buildAdaptiveBands(confirmedValidRows, 'confirmed');
							bandUpperSeries.setData(confirmedBands.upper);
							bandLowerSeries.setData(confirmedBands.lower);

							// Begin the dashed route at the final confirmed anchor so the
							// transition is continuous, then continue through provisional E1-E3.
							const confirmedSorted = confirmedValidRows.slice().sort((a, b) => Number(a.t) - Number(b.t));
							const bridge = provisionalRows.length && confirmedSorted.length
								? [confirmedSorted[confirmedSorted.length - 1]].concat(provisionalRows)
								: provisionalRows;
							const confirmedEnd = confirmedBands.upper.length && confirmedBands.lower.length ? {
								time: confirmedBands.upper[confirmedBands.upper.length - 1].time,
								upper: confirmedBands.upper[confirmedBands.upper.length - 1].value,
								lower: confirmedBands.lower[confirmedBands.lower.length - 1].value,
							} : null;
							const provisionalBands = buildAdaptiveBands(bridge, 'provisional', confirmedEnd);
							// Defensive seam invariant: even if future filtering or smoothing
							// changes, the first dashed pixel shares the rendered solid endpoint.
							if (confirmedEnd && provisionalBands.upper.length && provisionalBands.lower.length) {
								provisionalBands.upper[0] = { time: confirmedEnd.time, value: confirmedEnd.upper };
								provisionalBands.lower[0] = { time: confirmedEnd.time, value: confirmedEnd.lower };
							}
							bandUpperProvisionalSeries.setData(provisionalBands.upper);
							bandLowerProvisionalSeries.setData(provisionalBands.lower);

							const upperRows = confirmedRows.filter(r => r.high_resistance);
							const lowerRows = confirmedRows.filter(r => r.low_support);
							bandUpperSeries.setMarkers(upperRows.map(r => ({
								time: Math.floor(r.t / 1000) + tzOffset,
								position: 'inBar',
								color: chartColors.bandUpper,
								shape: 'circle',
								size: 1,
								text: r.high_resistance_positive ? '+' : '-',
							})));
							bandLowerSeries.setMarkers(lowerRows.map(r => ({
								time: Math.floor(r.t / 1000) + tzOffset,
								position: 'inBar',
								color: chartColors.bandLower,
								shape: 'circle',
								size: 1,
								text: r.low_support_positive ? '+' : '-',
							})));
							// Low-confidence values are never hidden. Dashed paths plus a
							// warning marker distinguish them from confirmed structure.
							bandUpperProvisionalSeries.setMarkers(provisionalRows.filter(r => r.quality_status === 'low').map(r => ({
								time: Math.floor(r.t / 1000) + tzOffset,
								position: 'aboveBar', color: '#ffb300', shape: 'circle', size: 1,
								text: '! ' + (r.quality_reason || 'LOW DATA'),
							})));
							bandLowerProvisionalSeries.setMarkers([]);
						} else {
							clearBandOnlyLines();
						}

						// Smart Liquidity is sourced exclusively from dankbit.live.band's
						// own hourly history (see refreshLiveBandDots) — dankbit.bands'
						// per-instrument term structure used to be mixed in here as a
						// second, independently-computed data source for the same lines,
						// which is what was producing two visibly different dotted routes.
						// This function no longer touches Smart Liquidity data at all; it
						// only clears the lines when the checkbox is off. The active renderer
						// supports midnight as well as the 2h/4h option-flow previews; clearing
						// here during a preview caused a race that could erase a valid layer.
						if (!SHOW_SMART_LIQUIDITY) {
							clearSmartLiquidityLines();
						}
					}

					function median(values) {
						if (!values.length) return null;
						const sorted = values.slice().sort((a, b) => a - b);
						const mid = Math.floor(sorted.length / 2);
						return sorted.length % 2 ? sorted[mid] : (sorted[mid - 1] + sorted[mid]) / 2;
					}

					function candleCloseAt(time) {
						if (!realCandles.length) return null;
						let lo = 0, hi = realCandles.length - 1, found = null;
						while (lo <= hi) {
							const mid = Math.floor((lo + hi) / 2);
							if (realCandles[mid].time <= time) { found = realCandles[mid]; lo = mid + 1; }
							else hi = mid - 1;
						}
						return found ? Number(found.close) : null;
					}

					function smartLiqDisplayBucket(time) {
						const bucket = INTERVAL_SECONDS[INTERVAL] || 3600;
						const utcTime = time - tzOffset;
						return Math.floor(utcTime / bucket) * bucket + tzOffset;
					}

					// One route only: keep the accepted hourly observations on their
					// native path and connect the latest observation directly to E1,
					// then E1→E2→E3. No eased/ATR-smoothed bridge is generated.
					// Missing historical buckets break the historical line, while
					// expiry points are deliberately connected across their wider gaps.
					function directSmartLiqPath(history, termPoints) {
						const result = [];
						const stepSeconds = INTERVAL_SECONDS[INTERVAL] || 3600;
						let previousTime = null;
						(history || []).slice().sort((a, b) => a.time - b.time).forEach(p => {
							if (previousTime !== null && p.time - previousTime > stepSeconds * 1.5) {
								result.push({ time: previousTime + stepSeconds, isGap: true });
							}
							result.push({ time: p.time, value: Number(p.value), isTerm: false });
							previousTime = p.time;
						});
						const cutoff = previousTime === null ? -Infinity : previousTime;
						(termPoints || []).slice().sort((a, b) => a.time - b.time).forEach(p => {
							if (p.time > cutoff && Number.isFinite(Number(p.value))) {
								result.push({ time: p.time, value: Number(p.value), isTerm: true });
							}
						});
						return result;
					}

					// Marks the dominant side directly on the single Smart Liquidity line
					// via setMarkers() rather than a second overlapping line series.
					// A prior version drew a thicker line only on the dominant side's own
					// points, leaving the rest as blank "whitespace" points on that same
					// series — relying on Lightweight Charts breaking the line at those
					// blanks. It does not: confirmed empirically that a whitespace point
					// (however many in a row) does not stop the library from drawing a
					// straight connector to the next real value, so whenever dominance
					// flipped more than once, both the base and "dominant" series ended up
					// drawing false diagonals connecting non-adjacent points — read as two
					// lines. Markers don't have that failure mode: they're independent of
					// how the line itself connects. size 2 on the dominant side's own
					// points, size 0 (invisible) elsewhere.
					function smartLiqDominanceMarkers(path, wantedState, dominanceAt) {
						const color = wantedState === 'upper' ? chartColors.smartLiqUpper : chartColors.smartLiqLower;
						const markers = [];
						(path || []).forEach(p => {
							if (p.isGap || dominanceAt(p.time) !== wantedState) return;
							markers.push({ time: p.time, position: 'inBar', color, shape: 'circle', size: 0.5 });
						});
						return markers;
					}

					// Clean Smart Liquidity envelope: native hourly scans determine
					// dominance, while geometry is validated against price, resampled to
					// the selected timeframe, smoothed, and only then bridged to future
					// expiry points. Historical and term-structure data are never directly
					// concatenated again.
					// Retained temporarily as a named compatibility reference for old
					// deployments; never called. The active renderer below is the only
					// function bound to refreshLiveBandDots.
					async function refreshLiveBandDotsLegacyDisabled() {
						if (MINIMAL_CHART || !SHOW_SMART_LIQUIDITY) return;
						if (selectedOptionFlowHours() !== null) {
							liveBandUpperSeries.setData([]); liveBandLowerSeries.setData([]);
							liveBandUpperSeries.setMarkers([]); liveBandLowerSeries.setMarkers([]);
							return;
						}
						const data = await (await fetch(LIVE_BAND_URL)).json();
						if (!SHOW_SMART_LIQUIDITY) return;
						const allLivePoints = data.points || [];
						const atr = recentAtr();
						const earliest = realCandles.length ? realCandles[0].time : -Infinity;
						const byHour = new Map();
						allLivePoints.forEach(p => {
							// The rolling historical envelope follows E1. E2/E3 have
							// their own hourly histories, but their latest confirmed readings
							// belong to the future 24–48h/48–72h sections below.
							if (Number(p.expiry_index || 0) !== 0) return;
							const time = Math.floor(Math.floor(p.t / 1000) / 3600) * 3600 + tzOffset;
							if (time >= earliest) byHour.set(time, Object.assign({ time }, p));
						});
						const hourly = Array.from(byHour.values()).sort((a, b) => a.time - b.time);

						let confirmed = 'neutral', lastDominant = null;
						let candidate = null, candidateCount = 0;
						const accepted = [];
						hourly.forEach(p => {
							const price = candleCloseAt(p.time);
							const rawUpper = Number(p.smart_liq_upper || 0), rawLower = Number(p.smart_liq_lower || 0);
							const maxDistance = atr > 0 ? 4 * atr : Infinity;
							const upperValid = price && rawUpper > price && rawUpper - price <= maxDistance;
							const lowerValid = price && rawLower < price && price - rawLower <= maxDistance;
							if (!upperValid || !lowerValid || rawUpper <= rawLower) return;

							const upperStrength = Math.max(0, Number(p.smart_liq_upper_strength || 0));
							const lowerStrength = Math.max(0, Number(p.smart_liq_lower_strength || 0));
							const total = upperStrength + lowerStrength;
							const upperShare = total > 0 ? upperStrength / total : 0.5;
							// The raw share sits within a few points of 50/50 almost every
							// hour, so flipping "confirmed" on a bare >50% crossing thickened
							// and thinned the line dozens of times across the visible window
							// instead of holding clean, meaningful stretches. A transfer now
							// needs two consecutive hourly scans clearing a 60/40 band before
							// it's confirmed — same debounce a since-removed earlier draft of
							// this renderer already used for the same reason.
							const target = upperShare >= 0.60 ? 'upper' : (upperShare <= 0.40 ? 'lower' : 'neutral');
							let transfer = null;
							if (target === 'neutral' || target === confirmed) {
								candidate = null;
								candidateCount = 0;
							} else {
								candidateCount = candidate === target ? candidateCount + 1 : 1;
								candidate = target;
								if (candidateCount >= 2) {
									if (lastDominant && lastDominant !== target) transfer = lastDominant === 'upper' ? 'U→L' : 'L→U';
									confirmed = target;
									lastDominant = target;
									candidate = null;
									candidateCount = 0;
								}
							}
							accepted.push({ time: p.time, upper: rawUpper, lower: rawLower, price, upperShare, lowerShare: 1 - upperShare, total, state: confirmed, transfer });
						});

						const bucketMap = new Map();
						accepted.forEach(p => {
							const time = smartLiqDisplayBucket(p.time);
							if (!bucketMap.has(time)) bucketMap.set(time, []);
							bucketMap.get(time).push(p);
						});
						const buckets = Array.from(bucketMap.keys()).sort((a, b) => a - b).map(time => {
							const group = bucketMap.get(time), last = group[group.length - 1];
							return {
								time, upper: median(group.map(p => p.upper)), lower: median(group.map(p => p.lower)),
								price: median(group.map(p => p.price)), state: last.state,
								upperShare: group.reduce((s, p) => s + p.upperShare, 0) / group.length,
								lowerShare: group.reduce((s, p) => s + p.lowerShare, 0) / group.length,
								total: group.reduce((s, p) => s + p.total, 0),
								transfer: (group.filter(p => p.transfer).slice(-1)[0] || {}).transfer || null,
							};
						});

						// No geometric smoothing: display the validated median reading of
						// each chart bucket directly. This makes the base and thickness
						// layers share one unambiguous route.
						const upperHistory = buckets.map(p => ({ time: p.time, value: p.upper }));
						const lowerHistory = buckets.map(p => ({ time: p.time, value: p.lower }));

						const liveByExpiry = new Map();
						allLivePoints.forEach(p => {
							const idx = Number(p.expiry_index || 0);
							if (!liveByExpiry.has(idx)) liveByExpiry.set(idx, []);
							liveByExpiry.get(idx).push(p);
						});
						const liveTerms = [];
						for (let idx = 0; idx < 3; idx++) {
							const history = (liveByExpiry.get(idx) || []).slice().sort((a, b) => a.t - b.t);
							const latestRow = history.length ? history[history.length - 1] : null;
							if (!latestRow || !latestRow.expiration) continue;
							let state = 'neutral';
							history.forEach(row => {
								const u = Math.max(0, Number(row.smart_liq_upper_strength || 0));
								const l = Math.max(0, Number(row.smart_liq_lower_strength || 0));
								const share = u + l > 0 ? u / (u + l) : 0.5;
								state = share > 0.50 ? 'upper' : (share < 0.50 ? 'lower' : 'neutral');
							});
							liveTerms.push({
								idx, time: Math.floor(latestRow.expiration / 1000) + tzOffset,
								upper: Number(latestRow.smart_liq_upper || 0), lower: Number(latestRow.smart_liq_lower || 0), state,
							});
						}
						liveTerms.sort((a, b) => a.time - b.time);
						const liveUpperTerms = liveTerms.filter(p => p.upper > 0).map(p => ({ time: p.time, value: p.upper }));
						const liveLowerTerms = liveTerms.filter(p => p.lower > 0).map(p => ({ time: p.time, value: p.lower }));
						// dankbit.bands' own per-instrument term structure is a separate,
						// independently-computed data source and is no longer mixed in
						// here — the future E1/E2/E3 bridge is built solely from this
						// same dankbit.live.band response's own per-expiry rows above.
						const upperPath = directSmartLiqPath(upperHistory, liveUpperTerms);
						const lowerPath = directSmartLiqPath(lowerHistory, liveLowerTerms);

						const historicalState = new Map(buckets.map(p => [p.time, p.state]));
						const lastHistoricalTime = buckets.length ? buckets[buckets.length - 1].time : -Infinity;
						function dominanceAt(time) {
							if (time <= lastHistoricalTime) return historicalState.get(time) || 'neutral';
							for (const term of liveTerms) if (time <= term.time) return term.state;
							return liveTerms.length ? liveTerms[liveTerms.length - 1].state : 'neutral';
						}
						// One single dotted line per side, always fully connected — no more
						// second "dominant" series relying on whitespace breaks (see
						// smartLiqDominanceMarkers). Dominance is a marker overlay on this
						// same line instead.
						smartLiqUpperSeries.setData(upperPath.map(p => p.isGap ? { time: p.time } : { time: p.time, value: p.value }));
						smartLiqLowerSeries.setData(lowerPath.map(p => p.isGap ? { time: p.time } : { time: p.time, value: p.value }));
						smartLiqUpperSeries.setMarkers(smartLiqDominanceMarkers(upperPath, 'upper', dominanceAt));
						smartLiqLowerSeries.setMarkers(smartLiqDominanceMarkers(lowerPath, 'lower', dominanceAt));

						// The dominance markers above already communicate every U↔L
						// transfer. Keep only the latest percentage label so old transfer
						// text can't clutter the line.
						const upperData = [], lowerData = [], upperMarkers = [], lowerMarkers = [];
						const latest = buckets.length ? buckets[buckets.length - 1] : null;
						if (latest) {
							const onUpper = latest.state !== 'lower', value = onUpper ? latest.upper : latest.lower;
							const marker = { time: latest.time, position: 'inBar', shape: 'circle', size: 1, color: onUpper ? chartColors.smartLiqUpper : chartColors.smartLiqLower, text: `U ${Math.round(latest.upperShare * 100)}% | L ${Math.round(latest.lowerShare * 100)}%` };
							if (onUpper) { upperData.push({ time: latest.time, value }); upperMarkers.push(marker); }
							else { lowerData.push({ time: latest.time, value }); lowerMarkers.push(marker); }
						}
						liveBandUpperSeries.setData(upperData); liveBandLowerSeries.setData(lowerData);
						liveBandUpperSeries.setMarkers(upperMarkers); liveBandLowerSeries.setMarkers(lowerMarkers);
					}

					// Final Smart Liquidity renderer. The two dashed envelope lines keep
					// one fixed user-selected color/opacity. Hourly scans control only the
					// three moving E1/E2/E3 circles; they never recolor a line or add
					// hourly price points to its geometry.

					function ensureSmartLiqMarkerLayer() {
						if (!smartLiqMarkerLayer) {
							const host = document.getElementById('chart-container');
							if (!host) return null;
							if (getComputedStyle(host).position === 'static') host.style.position = 'relative';
							smartLiqMarkerLayer = document.createElement('div');
							Object.assign(smartLiqMarkerLayer.style, {
								position: 'absolute', inset: '0', pointerEvents: 'none', zIndex: '8', overflow: 'hidden',
							});
							host.appendChild(smartLiqMarkerLayer);
						}
						if (!smartLiqMarkerObserversInstalled) {
							smartLiqMarkerObserversInstalled = true;
							chart.timeScale().subscribeVisibleLogicalRangeChange(() => positionSmartLiqTermMarkers());
							window.addEventListener('resize', () => positionSmartLiqTermMarkers());
						}
						return smartLiqMarkerLayer;
					}

					function setSmartLiquidityStatus(missingTerms) {
						const status = document.getElementById('smart-liquidity-status');
						if (!status) return;
						const missing = missingTerms || [];
						status.textContent = missing.length ? '⚠ LOW LIQ DATA: ' + missing.join('/') : '';
						status.title = missing.length
							? 'Smart Liquidity is still displayed from every valid expiry; listed expiries are missing or collapsed.'
							: '';
						status.style.display = missing.length ? 'inline-block' : 'none';
					}

					function positionSmartLiqTermMarkers() {
						const layer = ensureSmartLiqMarkerLayer();
						if (!layer || !SHOW_SMART_LIQUIDITY || !smartLiqTermState.length) {
							if (layer) layer.replaceChildren();
							return;
						}
						layer.replaceChildren();
						// All three circles advance by one twenty-fourth of their own
						// interval at every UTC hourly scan. Their x position is a DOM
						// overlay interpolated between existing expiry coordinates, so it
						// never inserts off-grid timestamps or gaps into 4H/1D candles.
						const nowSeconds = Date.now() / 1000;
						const secondsIntoUtcDay = ((nowSeconds % 86400) + 86400) % 86400;
						// Step once per completed UTC hourly scan, rather than drifting
						// continuously between scans when the chart is resized or panned.
						const utcDayProgress = Math.floor(secondsIntoUtcDay / 3600) / 24;
						const defaultSpan = smartLiqTermState.length > 1
							? (smartLiqTermState[1].time - smartLiqTermState[0].time || 86400)
							: 86400;
						smartLiqTermState.forEach((term, idx) => {
							const start = idx === 0
								? Object.assign({}, term, { time: term.time - defaultSpan })
								: smartLiqTermState[idx - 1];
							const x0 = chart.timeScale().timeToCoordinate(start.time);
							const x1 = chart.timeScale().timeToCoordinate(term.time);
							if (x0 === null || x1 === null) return;
							const state = term.state;
							const upperValue = start.upper + utcDayProgress * (term.upper - start.upper);
							const lowerValue = start.lower + utcDayProgress * (term.lower - start.lower);
							const value = state === 'upper' ? upperValue : (state === 'lower' ? lowerValue : (upperValue + lowerValue) / 2);
							const priceSeries = state === 'lower' ? smartLiqLowerSeries : smartLiqUpperSeries;
							const y = priceSeries.priceToCoordinate(value);
							if (y === null) return;
							const x = x0 + utcDayProgress * (x1 - x0);
							const color = state === 'upper' ? chartColors.smartLiqUpper : (state === 'lower' ? chartColors.smartLiqLower : '#777777');
							const marker = document.createElement('div');
							Object.assign(marker.style, {
								position: 'absolute', left: (x - 5) + 'px', top: (y - 5) + 'px',
								width: '10px', height: '10px', borderRadius: '50%', background: color,
								boxShadow: '0 0 0 1px rgba(255,255,255,0.9)', pointerEvents: 'auto',
							});
							const label = document.createElement('span');
							label.textContent = 'EA' + (term.idx + 1);
							Object.assign(label.style, {
								position: 'absolute', left: '-3px', top: '-18px', color,
								font: '600 11px monospace', whiteSpace: 'nowrap',
							});
							marker.title = `E${term.idx + 1} · ${state === 'neutral' ? '50/50' : state + ' dominant'} · U ${Math.round(term.upperShare * 100)}% / L ${Math.round(term.lowerShare * 100)}% · scan ${term.scanTimeText}`;
							marker.appendChild(label);
							layer.appendChild(marker);
						});
					}

					async function refreshLiveBandDots() {
						if (MINIMAL_CHART || !SHOW_SMART_LIQUIDITY) {
							clearSmartLiquidityLines();
							return;
						}
						const previewHours = selectedOptionFlowHours();
						// The standard view reads the hourly Smart-Liquidity log. A 2h/4h
						// preview instead reads the fresh term structure already returned by
						// /api/bands?hours=N. Both sources are normalized into the same three
						// E1/E2/E3 row shape below; changing the window never hides the layer.
						const data = previewHours === null
							? await (await fetch(LIVE_BAND_URL)).json()
							: await (await fetch(withOptionFlowWindow(BANDS_URL))).json();
						if (!SHOW_SMART_LIQUIDITY) return;
						const byExpiry = new Map();
						const sourceRows = previewHours === null
							? (data.points || [])
							: (data.bands || []).slice(-3).map((row, idx) => ({
								expiry_index: idx,
								t: Date.parse(data.generated_at || new Date().toISOString()),
								expiration: Number(row.t),
								smart_liq_upper: row.smart_liq_upper_price,
								smart_liq_lower: row.smart_liq_lower_price,
								smart_liq_upper_strength: row.smart_liq_upper_strength,
								smart_liq_lower_strength: row.smart_liq_lower_strength,
							}));
						sourceRows.forEach(row => {
							const idx = Number(row.expiry_index);
							if (!Number.isInteger(idx) || idx < 0 || idx > 2 || !row.expiration) return;
							if (!byExpiry.has(idx)) byExpiry.set(idx, []);
							byExpiry.get(idx).push(row);
						});

						const gridSeconds = INTERVAL_SECONDS[INTERVAL] || 3600;
						const terms = [];
						const missingTerms = [];
						for (let idx = 0; idx < 3; idx++) {
							const history = (byExpiry.get(idx) || []).slice().sort((a, b) => Number(a.t) - Number(b.t));
							const row = history.length ? history[history.length - 1] : null;
							if (!row) { missingTerms.push('E' + (idx + 1)); continue; }
							const upper = Number(row.smart_liq_upper || 0);
							const lower = Number(row.smart_liq_lower || 0);
							if (!(upper > lower && lower > 0)) { missingTerms.push('E' + (idx + 1)); continue; }
							const u = Math.max(0, Number(row.smart_liq_upper_strength || 0));
							const l = Math.max(0, Number(row.smart_liq_lower_strength || 0));
							const upperShare = u + l > 0 ? u / (u + l) : 0.5;
							const rawTime = Math.floor(Number(row.expiration) / 1000) + tzOffset;
							const utcTime = rawTime - tzOffset;
							terms.push({
								idx, time: Math.floor(utcTime / gridSeconds) * gridSeconds + tzOffset,
								upper, lower, upperShare, lowerShare: 1 - upperShare,
								state: upperShare > 0.5 ? 'upper' : (upperShare < 0.5 ? 'lower' : 'neutral'),
								scanTimeText: new Date(Number(row.t)).toISOString().slice(0, 16).replace('T', ' ') + ' UTC'
									+ (previewHours === null ? '' : ` · ${previewHours}h window`),
							});
						}
						terms.sort((a, b) => a.idx - b.idx);
						setSmartLiquidityStatus(missingTerms);
						if (!terms.length) {
							clearSmartLiquidityLines();
							return;
						}

						const firstSpan = terms.length > 1 ? (terms[1].time - terms[0].time || 86400) : 86400;
						const start = {
							time: terms[0].time - firstSpan,
							upper: terms[0].upper, lower: terms[0].lower,
							upperShare: terms[0].upperShare, lowerShare: terms[0].lowerShare,
						};
						const lineTerms = [start].concat(terms);
						smartLiqUpperPoints = lineTerms.map(p => ({ time: p.time, value: p.upper }));
						smartLiqLowerPoints = lineTerms.map(p => ({ time: p.time, value: p.lower }));
						smartLiqUpperSeries.setData(smartLiqUpperPoints);
						smartLiqLowerSeries.setData(smartLiqLowerPoints);
						smartLiqUpperSeries.setMarkers([]);
						smartLiqLowerSeries.setMarkers([]);
						liveBandUpperSeries.setData([]); liveBandLowerSeries.setData([]);
						liveBandUpperSeries.setMarkers([]); liveBandLowerSeries.setMarkers([]);
						smartLiqTermState = terms;
						requestAnimationFrame(() => positionSmartLiqTermMarkers());
					}

					function setBoxData(boxSeries, bottomLineSeries, top, bottom, fromTime, toTime) {
						// 0.0 is the "no crossing at all" sentinel (see
						// dankbit.bands) — nothing real to draw on that edge.
						if (!top && !bottom) { boxSeries.setData([]); bottomLineSeries.setData([]); return; }
						if (top && bottom && top !== bottom) {
							boxSeries.applyOptions({ baseValue: { type: 'price', price: bottom } });
							boxSeries.setData([
								{ time: fromTime, value: top },
								{ time: toTime, value: top },
							]);
							bottomLineSeries.setData([
								{ time: fromTime, value: bottom },
								{ time: toTime, value: bottom },
							]);
							return;
						}
						// Only one edge has a crossing, or both coincide (zero-height
						// box) — can't draw a rectangle, so draw a single line at
						// whichever price we do have instead of dropping it silently.
						const price = top || bottom;
						boxSeries.setData([]);
						bottomLineSeries.setData([
							{ time: fromTime, value: price },
							{ time: toTime, value: price },
						]);
					}

					function clearZonesBoxes() {
						aboveBoxSeries.setData([]);
						belowBoxSeries.setData([]);
						aboveBoxBottomLine.setData([]);
						belowBoxBottomLine.setData([]);
						smpBmlBoxSeries.setData([]);
						smpBmlBoxBottomLine.setData([]);
						zonesBoxAutoHours = null;
						updateStatusLine();
					}

					async function refreshZonesBoxes() {
						if (MINIMAL_CHART || !SHOW_ZONES_BOXES) return;
						// Live lookup — computed fresh by the server on every call (see
						// dankbit.bands.get_box), not read from stored history.
						// The midnight path serves the persisted confirmed zone. Any
						// trailing selection adds ?hours= and makes the server compute a
						// display-only live preview instead — see
						// ZONES_BOX_WINDOW_MODE above.
						// 'auto' is zones-boxes-only: send ?hours=auto and let the
						// server size the window off the nearest expiry's DTE (see
						// _auto_window_hours / zones_box_json). withOptionFlowWindow()
						// deliberately ignores 'auto' so Bands/Smart Liquidity/Forecast
						// stay on their default 00:00-UTC view.
						const url = ZONES_BOX_WINDOW_MODE === 'auto'
							? ZB_URL + (ZB_URL.includes('?') ? '&' : '?') + 'hours=auto'
							: withOptionFlowWindow(ZB_URL);
						const data = await (await fetch(url)).json();
						// Re-check: the "Zones" checkbox may have been switched off
						// while this fetch was in flight (e.g. a periodic poll or a
						// timeframe switch) — the guard at the top of this function
						// only ran before the request started, so without this the
						// boxes would still get redrawn a few seconds after being
						// unchecked once this stale response arrives.
						if (!SHOW_ZONES_BOXES) return;
						// Footer "Option Flow: Auto → <N>h" text — only while the
						// dropdown is on "Auto" and the server echoed a resolved
						// window_hours; every other mode leaves it null (see
						// zonesBoxAutoHours / updateStatusLine).
						zonesBoxAutoHours = (ZONES_BOX_WINDOW_MODE === 'auto' && typeof data.window_hours === 'number')
							? data.window_hours : null;
						updateStatusLine();
						if (!data || data.t === undefined) {
							clearZonesBoxes();
							return;
						}
						// Every visible series must use the selected candle grid. An
						// option expiration commonly lands at 08:00 UTC; placing that raw
						// timestamp on a 1D chart inserts an extra logical slot between two
						// consecutive daily forecast candles. Bucket both zone endpoints
						// onto the same 1H/4H/1D grid as the market and forecast series.
						const gridSeconds = INTERVAL_SECONDS[INTERVAL] || 3600;
						const bucketToChartGrid = time => {
							const utcTime = time - tzOffset;
							return Math.floor(utcTime / gridSeconds) * gridSeconds + tzOffset;
						};
						const fromTime = bucketToChartGrid(Math.floor(Date.now() / 1000) + tzOffset - 10 * 86400);
						const toTime   = bucketToChartGrid(Math.floor(data.expiration / 1000) + tzOffset);

						const aboveTop    = Math.max(data.short_zero_above_price, data.long_zero_above_price);
						const aboveBottom = Math.min(data.short_zero_above_price, data.long_zero_above_price);
						setBoxData(aboveBoxSeries, aboveBoxBottomLine, aboveTop, aboveBottom, fromTime, toTime);

						const belowTop    = Math.max(data.short_zero_below_price, data.long_zero_below_price);
						const belowBottom = Math.min(data.short_zero_below_price, data.long_zero_below_price);
						setBoxData(belowBoxSeries, belowBoxBottomLine, belowTop, belowBottom, fromTime, toTime);

						// Seller Max Profit / Buyer Max Loss box — same fromTime/toTime as the yellow box
						// above, since both come from this same nearest-expiry get_box() call.
						const smpBmlTop    = Math.max(data.seller_max_profit, data.buyer_max_loss);
						const smpBmlBottom = Math.min(data.seller_max_profit, data.buyer_max_loss);
						setBoxData(smpBmlBoxSeries, smpBmlBoxBottomLine, smpBmlTop, smpBmlBottom, fromTime, toTime);
					}

					// "Zones" checkbox (Delta Chart only) —
					// controls the yellow High Zone/Low Zone boxes and the teal
					// Middle Zone (Seller Max Profit/Buyer Max Loss) box, i.e.
					// everything refreshZonesBoxes()/clearZonesBoxes() draw.
					// Checked by default (SHOW_ZONES_BOXES starts true, matching
					// the checkbox's own default-checked state), since these boxes
					// were always shown before this checkbox existed. Stops
					// refreshZonesBoxes() from calling the server at all while off
					// (see SHOW_ZONES_BOXES above), purely to reduce server load —
					// not just hiding the result; get_box() never persists to
					// dankbit.bands regardless, so this has no effect on that
					// model either way. The 4-hourly compute_snapshot() cron is
					// untouched either way. Clears the boxes immediately
					// when switched off and re-fetches immediately when switched
					// back on.
					function onToggleZonesBoxes() {
						SHOW_ZONES_BOXES = document.getElementById('zones-boxes-toggle').checked;
						if (SHOW_ZONES_BOXES) {
							refreshZonesBoxes();
						} else {
							clearZonesBoxes();
						}
					}

					// "Bands" checkbox (Delta Chart only, next to "Zones") —
					// controls only the High/Resistance + Low/Support + Gamma Band lines
					// (green/red/dashed violet), NOT the yellow/teal zones boxes,
					// which have their own separate "Zones" checkbox instead
					// (SHOW_ZONES_BOXES/onToggleZonesBoxes() above). refreshBands()
					// only ever reads the already-persisted dankbit.bands rows
					// (/api/bands/<asset>) — it never triggers a new computation.
					// Those rows are kept fresh solely by the 4-hourly compute_snapshot()
					// cron; toggling this checkbox, or this browser polling it, has no
					// effect on when new extrema get computed. Clears the lines
					// immediately when switched off (refreshBands() returns
					// before clearing when SHOW_BANDS is false) and re-fetches
					// immediately when switched back on.
					function onToggleBands() {
						SHOW_BANDS = document.getElementById('bands-toggle').checked;
						if (SHOW_BANDS) {
							refreshBands();
						} else {
							clearBandOnlyLines();
						}
					}

					function onToggleSmartLiquidity() {
						SHOW_SMART_LIQUIDITY = document.getElementById('smart-liquidity-toggle').checked;
						localStorage.setItem(SMART_LIQ_VISIBILITY_STORAGE_KEY, String(SHOW_SMART_LIQUIDITY));
						if (SHOW_SMART_LIQUIDITY) {
							refreshBands().then(refreshLiveBandDots);
						} else {
							setSmartLiquidityStatus([]);
							clearSmartLiquidityLines();
						}
					}

					// Rounds and abbreviates large raw dollar-gamma values
					// (hundreds of millions to billions is typical here) —
					// thousands as K, millions as M, sign preserved — same
					// convention four_leg_gamma_chart_templates.xml's own
					// formatAbbreviated() uses for its AVG-family lines.
					function clearForecastLines() {
						forecastSeries.setData([]);
						forecastSeries.setMarkers([]);
						const label = document.getElementById('forecast-status-label');
						if (label) { label.textContent = ''; label.classList.remove('forecast-risk-warning'); label.removeAttribute('title'); }
					}

					// Unified Forecast follows the selected real-candle grid:
					// 1H (up to 72), 4H (up to 18), or 1D (up to 3).
					// Called from setTf()/init() on both Delta and Gamma
					// Chart (both share setTf()), but the checkbox itself
					// only exists on the Delta Chart — guarded with a null
					// check rather than assuming the element is present.
					function updateForecastVisibility() {
						const visible = ['1h', '4h', '1d'].includes(INTERVAL);
						const wrap = document.getElementById('forecast-toggle-wrap');
						if (wrap) wrap.style.display = visible ? '' : 'none';
						repositionBelowToolbar();
						refreshForecast();
					}

					// "Thales Forecast" checkbox (Delta Chart only) —
					// fetches /api/forecast/<asset> and draws the forecast
					// candles (see FORECAST_URL, forecastSeries above). Stops
					// fetching entirely while off. On a timeframe switch it
					// requests the matching 1H/4H/1D engine and candle count,
					// server-load-reducing pattern as every other optional
					// indicator here. Display time is NOT taken from the
					// server's `t` (an arbitrary now-relative timestamp) — it's
					// recomputed here, anchored to the same grid
					// futureAxisSeries uses for its own future ticks
					// (realCandles[last].time, stepped by intervalSec).
					// Lightweight Charts builds one shared logical time axis
					// from the union of every series' timestamps; server-
					// relative "now" timestamps almost never land on that grid,
					// so forecastSeries' points ended up alternating with
					// futureAxisSeries' ticks in the same stretch — each series
					// only getting every other logical slot, which rendered as
					// every other forecast candle missing.
					//
					// The anchor walks forward from realCandles[last].time
					// (a whole number of intervalSec steps at a time, so it
					// never leaves the grid) until it's strictly past "now"
					// — rather than assuming realCandles[last] is always
					// the current still-forming candle (one step behind
					// "now"), which would silently break if Deribit or the
					// 5s updateLatestCandle() poll ever returned a stale
					// last-closed candle instead. This guarantees the first
					// forecast candle is always the next selected-timeframe candle after
					// now, on the correct grid, regardless of which one
					// realCandles[last] actually is.
					async function refreshForecast() {
						if (!SHOW_FORECAST || !['1h', '4h', '1d'].includes(INTERVAL) || !realCandles.length) { clearForecastLines(); return; }
						const requestedTf = INTERVAL;
						const requestedCount = forecastCandleCounts[requestedTf];
						const response = await fetch(withOptionFlowWindow(
							FORECAST_URL + '?timeframe=' + requestedTf + '&count=' + requestedCount
						));
						if (!response.ok) throw new Error('Forecast HTTP ' + response.status);
						const data = await response.json();
						if (data.error) throw new Error('Forecast: ' + data.error);
						// Re-check: "Thales Forecast" may have been switched off (or the
						// timeframe changed away from 4h) while this fetch was in
						// flight — onToggleForecast() already cleared the series
						// synchronously in that case, so just bail without redrawing.
						if (!SHOW_FORECAST || INTERVAL !== requestedTf) return;
						// The selected timeframe owns the hard display cap. In
						// particular, Daily can never draw more than the three
						// tracked expiries (E1/E2/E3), even if a stale server or
						// browser response happens to contain additional points.
						const points = (data.points || []).slice(0, requestedCount);
						if (!points.length) { clearForecastLines(); return; }
						const intervalSec = INTERVAL_SECONDS[INTERVAL];
						// Always start on the candle immediately following the last
						// market candle supplied by the API. The previous while-loop could
						// skip a whole daily slot when the current forming 1D candle was
						// temporarily absent, leaving a visible empty candle.
						const firstTime = realCandles[realCandles.length - 1].time + intervalSec;
						// Re-anchor the forecast geometry to the live chart. The
						// first forecast Open is exactly the latest real Close and
						// every later Open is exactly the preceding forecast Close.
						// Greek Flow still determines body direction/size and wick
						// geometry; only the absolute vertical anchor is translated.
						let chainedOpen = Number(realCandles[realCandles.length - 1].close);
						const renderedForecast = points.map((p, i) => {
							const rawOpen = Number(p.open);
							const rawClose = Number(p.close);
							const rawHigh = Number(p.high);
							const rawLow = Number(p.low);
							const body = rawClose - rawOpen;
							const upperWick = Math.max(0, rawHigh - Math.max(rawOpen, rawClose));
							const lowerWick = Math.max(0, Math.min(rawOpen, rawClose) - rawLow);
							const open = chainedOpen;
							const close = open + body;
							const candle = {
								time: firstTime + i * intervalSec,
								open, close,
								high: Math.max(open, close) + upperWick,
								low: Math.min(open, close) - lowerWick,
							};
							chainedOpen = close;
							return candle;
						});
						forecastSeries.setData(renderedForecast);
						const perDay = { '1h': 24, '4h': 6, '1d': 1 }[requestedTf];
						const anchors = data.anchors || [];
						// A marker represents a real Greek-Flow anchor.  Missing anchors
						// remain visible in the status text, never as a fake EA candle.
						const anchorSlots = [0, 1, 2].map(expiryIndex =>
							anchors.find(a => Number(a.expiry_index) === expiryIndex) || { expiry_index: expiryIndex, available: false, quality_tier: 'fallback', quality_weight: 0, unavailable_reason: 'not-generated-yet' }
						);
						forecastSeries.setMarkers(anchorSlots.filter(a => a.expiry_index * perDay < points.length).map(a => ({
							time: firstTime + Number(a.expiry_index) * perDay * intervalSec,
							position: 'aboveBar', shape: 'circle',
							color: a.quality_tier === 'valid' ? chartColors.gammaBand : (a.quality_tier === 'partial' ? '#ffb300' : (a.quality_tier === 'stale' ? '#ff7043' : '#9e9e9e')),
							text: 'EA' + (Number(a.expiry_index) + 1) + (a.quality_tier === 'valid' ? '' : '!'),
						})));
						const label = document.getElementById('forecast-status-label');
						if (label) {
							const availableAnchors = anchors.filter(a => a.available);
							const anchorReason = reason => {
								if (!reason || reason === 'not-generated-yet') return 'not generated';
								if (reason === 'stale-expiry-row') return 'stale expiry';
								if (reason === 'stale-target-row') return 'stale target';
								if (reason.indexOf('missing-critical-leg:') === 0) return 'missing ' + reason.split(':')[1];
								return reason;
							};
							const missingAnchors = anchorSlots.filter(a => !a.available)
								.map(a => 'EA' + (Number(a.expiry_index) + 1) + ' ' + anchorReason(a.unavailable_reason));
							const baseStatus = !availableAnchors.length
								? requestedTf.toUpperCase() + ' Forecast · Anchors 0/3 · ' + missingAnchors.join(' · ') + ' · ' + points.length + ' candle' + (points.length === 1 ? '' : 's')
								: requestedTf.toUpperCase() + ' Forecast · Anchors ' + availableAnchors.length + '/3 · '
									+ availableAnchors.map(a => 'EA' + (a.expiry_index + 1) + ' ' + String(a.quality_tier || 'valid').toUpperCase() + (a.expiry_instrument ? ' ' + a.expiry_instrument : '') + ' R' + a.revision + '/' + a.max_revisions + ' C' + Math.round(a.confidence) + '% W' + Math.round(Number(a.quality_weight == null ? 1 : a.quality_weight) * 100) + '%').join(' · ')
									+ (missingAnchors.length ? ' · ' + missingAnchors.join(' · ') : '')
									+ (availableAnchors[0].is_preview ? ' · ' + availableAnchors[0].window_hours + 'h Preview' : '')
									+ ' · ' + points.length + ' candle' + (points.length === 1 ? '' : 's');
							const risk = data.forecast_warning || {};
							label.classList.toggle('forecast-risk-warning', Boolean(risk.active));
							label.textContent = risk.active
								? '⚠ LOW OPTION DATA' + (risk.extreme ? ' / EXTREME FORECAST' : '') + ' · Q' + Number(risk.quality_score || 0).toFixed(0) + '% · ' + baseStatus
								: baseStatus;
							if (risk.active) {
								label.title = (risk.message_fa || risk.message || '') + ' Body ' + Number(risk.max_body_sigma || 0).toFixed(2) + 'σ / Path ' + Number(risk.max_path_sigma || 0).toFixed(2) + 'σ';
							} else {
								label.removeAttribute('title');
							}
						}
					}

					function onToggleForecast() {
						SHOW_FORECAST = document.getElementById('forecast-toggle').checked;
						if (SHOW_FORECAST) {
							refreshForecast();
						} else {
							clearForecastLines();
						}
					}

					function clearSignalBot() {
						signalBotRequestSeq += 1;
						signalBotPriceLines.forEach(line => series.removePriceLine(line));
						signalBotPriceLines = [];
						latestSignalBotData = null;
						SIGNAL_BOT_DETAILS_OPEN = false;
						const summary = document.getElementById('signal-bot-summary');
						if (summary) summary.textContent = 'OFF';
						const detailsButton = document.getElementById('signal-bot-details-button');
						if (detailsButton) detailsButton.textContent = 'Show signal details';
						const panel = document.getElementById('signal-bot-panel');
						if (panel) { panel.style.display = 'none'; panel.replaceChildren(); }
					}

					function toggleSignalBotMenu(event) {
						if (event) event.stopPropagation();
						const menu = document.getElementById('signal-bot-menu');
						if (menu) menu.classList.toggle('open');
					}

					function closeSignalBotMenu() {
						const menu = document.getElementById('signal-bot-menu');
						if (menu) menu.classList.remove('open');
					}

					function toggleSignalBotDetails() {
						SIGNAL_BOT_DETAILS_OPEN = !SIGNAL_BOT_DETAILS_OPEN;
						const button = document.getElementById('signal-bot-details-button');
						if (button) button.textContent = SIGNAL_BOT_DETAILS_OPEN ? 'Hide signal details' : 'Show signal details';
						closeSignalBotMenu();
						if (SIGNAL_BOT_DETAILS_OPEN && !SHOW_SIGNAL_BOT) {
							const toggle = document.getElementById('signal-bot-toggle');
							if (toggle) toggle.checked = true;
							SHOW_SIGNAL_BOT = true;
							refreshSignalBot();
							return;
						}
						if (SIGNAL_BOT_DETAILS_OPEN && latestSignalBotData) drawSignalBotPanel(latestSignalBotData);
						else {
							const panel = document.getElementById('signal-bot-panel');
							if (panel) panel.style.display = 'none';
						}
					}

					document.addEventListener('click', event => {
						const control = document.getElementById('signal-bot-control');
						if (control && !control.contains(event.target)) closeSignalBotMenu();
					});

					function signalMetric(grid, label, value) {
						const key = document.createElement('span');
						const val = document.createElement('span');
						key.textContent = label;
						val.textContent = value;
						grid.append(key, val);
					}

					function signalPrice(value) {
						const n = Number(value);
						return Number.isFinite(n) && n > 0 ? n.toLocaleString('en-US', { maximumFractionDigits: 2 }) : '—';
					}

					function drawSignalBotPanel(signal) {
						const panel = document.getElementById('signal-bot-panel');
						if (!panel) return;
						panel.replaceChildren();
						const isOfficial = signal.kind === 'official';
						const isShadow = signal.kind === 'shadow';
						const direction = signal.direction || 'neutral';
						const title = document.createElement('span');
						const state = document.createElement('span');
						const head = document.createElement('div');
						const close = document.createElement('button');
						head.className = 'signal-head';
						close.className = 'signal-close';
						close.type = 'button';
						close.title = 'Close details';
						close.textContent = '×';
						close.onclick = () => toggleSignalBotDetails();
						title.className = direction === 'long' ? 'signal-long' : direction === 'short' ? 'signal-short' : 'signal-neutral';
						title.textContent = signal.state === 'missed'
							? 'MISSED ENTRY ' + direction.toUpperCase()
							: isOfficial
							? 'OFFICIAL ' + direction.toUpperCase()
							: isShadow ? 'SHADOW ' + direction.toUpperCase()
							: signal.setup_path === 'breakout_retest' ? 'BREAKOUT WATCH ' + direction.toUpperCase()
							: signal.setup_stage === 'armed' ? 'ARMED ' + direction.toUpperCase()
							: signal.setup_stage === 'setup' ? 'SETUP ' + direction.toUpperCase() : 'NO TRADE';
						state.textContent = String(signal.state || '').toUpperCase();
						head.append(title, state, close);
						panel.append(head);
						const summary = document.getElementById('signal-bot-summary');
						if (summary) {
							const rr = Number(signal.risk_reward || 0) > 0 ? ' · 1:' + Number(signal.risk_reward).toFixed(1) : '';
							summary.textContent = title.textContent + rr;
						}

						const grid = document.createElement('div');
						grid.className = 'signal-grid';
						signalMetric(grid, 'Entry', signalPrice(signal.entry));
						signalMetric(grid, 'Stop', signalPrice(signal.stop_loss));
						signalMetric(grid, 'Target', signalPrice(signal.target));
						signalMetric(grid, 'R:R', Number(signal.risk_reward || 0) > 0 ? '1:' + Number(signal.risk_reward).toFixed(2) : '—');
						signalMetric(grid, 'Stage', String(signal.setup_stage || 'none').toUpperCase());
						signalMetric(grid, 'Path', String(signal.setup_path || '—').replaceAll('_', ' ').toUpperCase());
						signalMetric(grid, 'Plan Status', String(signal.plan_status || '—').toUpperCase() + (signal.plan_provisional ? ' · PROVISIONAL' : ''));
						signalMetric(grid, 'Entry Zone', Number(signal.entry_zone_low || 0) > 0 ? signalPrice(signal.entry_zone_low) + '–' + signalPrice(signal.entry_zone_high) : '—');
						signalMetric(grid, 'Invalidation', signalPrice(signal.invalidation_level));
						signalMetric(grid, 'TP2', signalPrice(signal.target_2));
						signalMetric(grid, 'Breakout Level', signalPrice(signal.breakout_level));
						signalMetric(grid, 'Trigger', signalPrice(signal.trigger_level));
						signalMetric(grid, 'Trigger Source', signal.trigger_basis || '—');
						signalMetric(grid, 'Liquidity Sweep', signal.liquidity_swept ? 'YES' : 'WAITING');
						signalMetric(grid, 'Entry Model', String(signal.entry_model || 'WAITING').replaceAll('_', ' ').toUpperCase());
						signalMetric(grid, 'Entry Source', signal.entry_source || '—');
						signalMetric(grid, 'Stop Source', signal.stop_source || signal.stop_basis || '—');
						signalMetric(grid, 'RTM Score', Number(signal.rtm_score || 0).toFixed(1) + ' / 100');
						signalMetric(grid, 'RTM Zone', signal.rtm_zone_type ? String(signal.rtm_zone_type).toUpperCase() + ' ' + signalPrice(signal.rtm_zone_low) + '–' + signalPrice(signal.rtm_zone_high) : '—');
						signalMetric(grid, 'RTM Structure', String(signal.rtm_structure || '—').toUpperCase());
						signalMetric(grid, 'Opposing RTM', signal.rtm_opposing_structure ? String(signal.rtm_opposing_structure).toUpperCase() + ' @ ' + signalPrice(signal.rtm_opposing_level) : 'NONE');
						signalMetric(grid, 'Path to 2R', signal.rtm_path_clear ? 'CLEAR' : 'BLOCKED');
						signalMetric(grid, 'RTM Touch', Number(signal.rtm_touch_count || 0) === 1 ? 'FTB' : Number(signal.rtm_touch_count || 0) > 1 ? Number(signal.rtm_touch_count) + 'TB' : 'WAITING');
						signalMetric(grid, 'RTM Quality', [signal.rtm_fresh ? 'FRESH' : '', signal.rtm_nested ? 'NESTED' : '', signal.rtm_compression ? 'CP' : '', signal.rtm_gap ? 'GAP' : ''].filter(Boolean).join(' · ') || '—');
						const detectedRtm = Array.isArray(signal.rtm_candidates_1h) ? signal.rtm_candidates_1h : [];
						signalMetric(grid, '1H RTM Detected', detectedRtm.length ? detectedRtm.slice(0, 6).map(z => String(z.structure || '?').toUpperCase() + ' ' + signalPrice(z.low) + '–' + signalPrice(z.high) + ' S' + Number(z.score || 0).toFixed(0)).join(' | ') : 'NONE');
						signalMetric(grid, 'Trend D-Macro / D-Tactical', [signal.trend_daily, signal.trend_daily_tactical].map(v => String(v || 'neutral').toUpperCase()).join(' / '));
						signalMetric(grid, 'Trend 4H / 1H', [signal.trend_4h, signal.trend_1h].map(v => String(v || 'neutral').toUpperCase()).join(' / '));
						signalMetric(grid, 'Gamma Direction', Number(signal.gamma_direction_score || 0).toFixed(1));
						signalMetric(grid, 'Greeks Direction', Number(signal.greek_direction_score || 0).toFixed(1));
						signalMetric(grid, 'Weekly Signals', Number(signal.weekly_signal_count || 0) + ' / ' + Number(signal.weekly_signal_limit || 3));
						signalMetric(grid, signal.direction === 'short' ? 'Swing High' : signal.direction === 'long' ? 'Swing Low' : 'Swing', signalPrice(signal.swing_level));
						signalMetric(grid, 'ATR 4H', signalPrice(signal.atr_4h));
						signalMetric(grid, 'Quality', Number(signal.quality_score || 0).toFixed(1) + '%');
						signalMetric(grid, 'Score', Number(signal.final_score || 0).toFixed(1));
						const evaluated = signal.evaluated_at ? signal.evaluated_at.replace('T', ' ').slice(0, 16) + ' UTC' : '—';
						signalMetric(grid, 'Evaluated', evaluated);
						signalMetric(grid, 'Validity', signal.expires_at ? signal.expires_at.replace('T', ' ').slice(0, 16) + ' UTC' : '—');
						panel.append(grid);

						const reason = document.createElement('div');
						reason.className = 'signal-reason';
						reason.textContent = (signal.stop_basis ? signal.stop_basis + ' · ' : '') + (signal.reason || 'No explanation recorded.');
						panel.append(reason);
						panel.style.display = SIGNAL_BOT_DETAILS_OPEN ? 'block' : 'none';
					}

					async function refreshSignalBot() {
						if (!SHOW_SIGNAL_BOT || MINIMAL_CHART) return;
						const requestSeq = ++signalBotRequestSeq;
						try {
							const response = await fetch(SIGNAL_BOT_URL, { cache: 'no-store' });
							if (!response.ok) throw new Error('Signal Bot HTTP ' + response.status);
							const data = await response.json();
							if (!SHOW_SIGNAL_BOT || requestSeq !== signalBotRequestSeq) return;
							signalBotPriceLines.forEach(line => series.removePriceLine(line));
							signalBotPriceLines = [];
							if (!data.signal) {
								latestSignalBotData = { kind:'no_trade', state:'waiting', direction:'neutral', reason:'No Signal Bot evaluation has been recorded for this UTC day.' };
								drawSignalBotPanel(latestSignalBotData);
								return;
							}
							const signal = data.signal;
							latestSignalBotData = signal;
							drawSignalBotPanel(signal);
							// Potential plans are deliberately visible before the official
							// trigger. Dashed lines mean WATCH/SHADOW; a triggered official
							// plan switches to solid lines.
							const hasPlan = Number(signal.entry || 0) > 0 && Number(signal.stop_loss || 0) > 0;
							if (!hasPlan) return;
							const officialTriggered = signal.kind === 'official' && signal.plan_status === 'triggered';
							const prefix = officialTriggered ? 'BOT' : 'PLAN';
							const definitions = [
								{ value:signal.entry_zone_low || signal.entry, color:'#42a5f5', title:prefix + ' ENTRY LOW' },
								{ value:signal.entry_zone_high || signal.entry, color:'#1e88e5', title:prefix + ' ENTRY HIGH' },
								{ value:signal.stop_loss, color:'#ef5350', title:prefix + (signal.plan_provisional ? ' INVALIDATION' : ' SL') },
								{ value:signal.target, color:'#26a69a', title:prefix + ' TP1' },
								{ value:signal.target_2, color:'#66bb6a', title:prefix + ' TP2' },
							];
							const drawnPrices = new Set();
							definitions.forEach(item => {
								const price = Number(item.value);
								if (!Number.isFinite(price) || price <= 0) return;
								const priceKey = price.toFixed(8);
								if (drawnPrices.has(priceKey)) return;
								drawnPrices.add(priceKey);
								signalBotPriceLines.push(series.createPriceLine({
									price, color:item.color, lineWidth:2,
									lineStyle:officialTriggered ? LightweightCharts.LineStyle.Solid : LightweightCharts.LineStyle.Dashed,
									axisLabelVisible:true, axisLabelColor:item.color, title:item.title,
								}));
							});
						} catch (error) {
							if (!SHOW_SIGNAL_BOT || requestSeq !== signalBotRequestSeq) return;
							latestSignalBotData = { kind:'no_trade', state:'error', direction:'neutral', reason:error.message };
							drawSignalBotPanel(latestSignalBotData);
						}
					}

					function onToggleSignalBot() {
						SHOW_SIGNAL_BOT = document.getElementById('signal-bot-toggle').checked;
						if (SHOW_SIGNAL_BOT) refreshSignalBot(); else clearSignalBot();
					}

					// Shared option-flow window for Zones, Gamma, Smart Liquidity and
					// the unified Forecast layer. Trailing selections are non-persisted.
					function onZonesBoxWindowChange() {
						ZONES_BOX_WINDOW_MODE = document.getElementById('zones-box-window-select').value;
						// Drop any stale "Auto → <N>h" footer text immediately;
						// refreshZonesBoxes() re-sets it if the new mode is 'auto'
						// (and won't touch it at all if the Zones checkbox is off).
						if (ZONES_BOX_WINDOW_MODE !== 'auto') { zonesBoxAutoHours = null; updateStatusLine(); }
						refreshZonesBoxes();
						refreshBands().then(refreshLiveBandDots);
						refreshForecast();
					}

					// "Light"/"Dark" radio (see DARK_MODE/axisBlack()/rulerColor()
					// above) — swaps the chart's own canvas-drawn colors via
					// chart.applyOptions() and toggles body.dark for the fixed HTML
					// overlays (status bar, toggle labels, exchange label, ruler
					// info, context menu — see the <style> block). Candle/box/band
					// series already use saturated colors that read fine on either
					// background, so only the chart chrome needs swapping here.
					function applyTheme() {
						document.body.classList.toggle('dark', DARK_MODE);
						chart.applyOptions({
							layout: {
								background: { type: 'solid', color: DARK_MODE ? '#000000' : '#ffffff' },
								textColor: DARK_MODE ? '#d1d4dc' : '#333333',
							},
							rightPriceScale: { borderColor: DARK_MODE ? '#444444' : '#cccccc' },
							timeScale: { borderColor: DARK_MODE ? '#444444' : '#cccccc' },
						});
						rsiChart.applyOptions({
							layout: { background:{ type:'solid', color:DARK_MODE ? '#000000' : '#ffffff' }, textColor:DARK_MODE ? '#d1d4dc' : '#333333' },
							rightPriceScale: { borderColor:DARK_MODE ? '#444444' : '#cccccc' },
							timeScale: { borderColor:DARK_MODE ? '#444444' : '#cccccc' },
						});
					}

					function onThemeChange() {
						DARK_MODE = document.getElementById('theme-select').value === 'dark';
						localStorage.setItem(THEME_STORAGE_KEY, DARK_MODE ? 'dark' : 'light');
						applyTheme();
						// Re-invoke every indicator whose own line stroke color is
						// theme-dependent (axisBlack()) so the switch takes effect
						// immediately instead of waiting for the next poll — each
						// already no-ops (or has already cleared its own lines) if
						// that indicator isn't currently shown/enabled.
						refreshGammaHorizon();
					}

					// "Settings" button/dialog (after Ruler, all 3 TV chart pages) —
					// re-applies the current colors and line styles to every already-created
					// series/line via applyOptions() rather than needing a
					// server round-trip or a full chart rebuild.
					function applyChartColors() {
						const c = chartColors;
						const s = chartLineStyles;
						const zonesRgba = hexToRgba(c.zonesBox, 0.25);
						aboveBoxSeries.applyOptions({ topLineColor: c.zonesBox, topFillColor1: zonesRgba, topFillColor2: zonesRgba, bottomLineColor: c.zonesBox, bottomFillColor1: zonesRgba, bottomFillColor2: zonesRgba });
						belowBoxSeries.applyOptions({ topLineColor: c.zonesBox, topFillColor1: zonesRgba, topFillColor2: zonesRgba, bottomLineColor: c.zonesBox, bottomFillColor1: zonesRgba, bottomFillColor2: zonesRgba });
						aboveBoxBottomLine.applyOptions({ color: c.zonesBox });
						belowBoxBottomLine.applyOptions({ color: c.zonesBox });

						const middleRgba = hexToRgba(c.middleZone, 0.25);
						smpBmlBoxSeries.applyOptions({ topLineColor: c.middleZone, topFillColor1: middleRgba, topFillColor2: middleRgba, bottomLineColor: c.middleZone, bottomFillColor1: middleRgba, bottomFillColor2: middleRgba });
						smpBmlBoxBottomLine.applyOptions({ color: c.middleZone });

						gammaBandSeries.applyOptions({ color: c.gammaBand, lineStyle: lineStyleFromName(s.gammaBand) });
						bandUpperSeries.applyOptions({ color: c.bandUpper, lineStyle: lineStyleFromName(s.bandUpper) });
						bandLowerSeries.applyOptions({ color: c.bandLower, lineStyle: lineStyleFromName(s.bandLower) });
						bandUpperProvisionalSeries.applyOptions({ color: hexToRgba(c.bandUpper, 0.68), lineStyle: LightweightCharts.LineStyle.Dashed });
						bandLowerProvisionalSeries.applyOptions({ color: hexToRgba(c.bandLower, 0.68), lineStyle: LightweightCharts.LineStyle.Dashed });
						smartLiqUpperSeries.applyOptions({ color: c.smartLiqUpper, lineStyle: lineStyleFromName(s.smartLiqUpper) });
						smartLiqLowerSeries.applyOptions({ color: c.smartLiqLower, lineStyle: lineStyleFromName(s.smartLiqLower) });
						forecastSeries.applyOptions({
							upColor: c.forecastUp, downColor: c.forecastDown,
							borderUpColor: c.forecastUp, borderDownColor: c.forecastDown,
							wickUpColor: c.forecastWickUp, wickDownColor: c.forecastWickDown,
						});

						// The dominance dots bake their color in at draw time (see
						// refreshLiveBandDots() above) rather than reading a
						// series-level option, so they need a redraw to pick up a
						// changed color immediately — harmless no-op if Bands is
						// currently off/not fetched yet. Sequenced, same reason as
						// onToggleBands() above.
						if (SHOW_BANDS || SHOW_SMART_LIQUIDITY) { refreshBands().then(refreshLiveBandDots); }
					}

					function populateGammaHorizonSettingsInputs() {
						['D1', 'W', 'M', 'YE'].forEach(kind => {
							const row = gammaHorizonSettings[kind];
							const visible = document.getElementById('gh-visible-' + kind);
							const color = document.getElementById('gh-color-' + kind);
							const style = document.getElementById('gh-style-' + kind);
							const width = document.getElementById('gh-width-' + kind);
							if (visible) visible.checked = row.visible;
							if (color) color.value = row.color;
							if (style) style.value = row.style;
							if (width) width.value = row.width;
						});
						const showLabels = document.getElementById('gh-show-labels');
						const showGreeks = document.getElementById('gh-show-greeks');
						if (showLabels) showLabels.checked = gammaHorizonSettings.showLabels;
						if (showGreeks) showGreeks.checked = gammaHorizonSettings.showGreeks;
						const recentColor=document.getElementById('gh-recent-color'),recentStyle=document.getElementById('gh-recent-style'),recentWidth=document.getElementById('gh-recent-width');
						if(recentColor)recentColor.value=gammaHorizonSettings.recent.color;if(recentStyle)recentStyle.value=gammaHorizonSettings.recent.style;if(recentWidth)recentWidth.value=gammaHorizonSettings.recent.width;
						renderGammaHorizonExpirySettings();
					}

					function renderGammaHorizonExpirySettings() {
						const selection=document.getElementById('gh-expiry-selector');const appearance=document.getElementById('gh-expiry-appearance');
						const levels=gammaHorizonData?.levels||[];if(selection)selection.replaceChildren();if(appearance)appearance.replaceChildren();
						if(!levels.length){[selection,appearance].filter(Boolean).forEach(root=>{const empty=document.createElement('div');empty.className='gh-menu-empty';empty.textContent='No active Gamma Horizon expiries available.';root.appendChild(empty);});updateGammaHorizonMenuCount();return;}
						levels.forEach(item=>{const base=gammaHorizonSettings[item.kind]||gammaHorizonSettings.W;const own=gammaHorizonSettings.expiries[item.expiry]||{};const date=new Date(item.expiry).toLocaleDateString('en-GB',{timeZone:'UTC',day:'2-digit',month:'short',year:'2-digit'}).toUpperCase();const title=item.kind+' · '+date+' · '+Number(item.price).toLocaleString(undefined,{maximumFractionDigits:2});
							if(selection){const menuLabel=document.createElement('label');menuLabel.className='gh-menu-expiry';const visible=document.createElement('input');visible.type='checkbox';visible.checked=own.visible!==false;visible.addEventListener('change',()=>setGammaHorizonExpiryVisible(item.expiry,visible.checked));const menuName=document.createElement('span');menuName.textContent=title;const mode=document.createElement('select');[['structural','Structural'],['recent','Recent'],['compare','Compare']].forEach(pair=>{const option=document.createElement('option');option.value=pair[0];option.textContent=pair[1];mode.appendChild(option);});mode.value=own.mode||'structural';mode.disabled=!Number.isFinite(Number(item.recent?.price));mode.addEventListener('click',event=>event.stopPropagation());mode.addEventListener('change',()=>setGammaHorizonExpiryMode(item.expiry,mode.value));menuLabel.append(visible,menuName,mode);selection.appendChild(menuLabel);}
							if(!appearance)return;const label=document.createElement('label');label.className='gamma-horizon-row';label.dataset.ghExpiry=item.expiry;const name=document.createElement('span');name.textContent=title;
							const color=document.createElement('input');color.type='color';color.className='gh-expiry-color';color.value=own.color||base.color;
							const style=document.createElement('select');style.className='gh-expiry-style';['solid','dashed','dotted'].forEach(value=>{const option=document.createElement('option');option.value=value;option.textContent=value[0].toUpperCase()+value.slice(1);style.appendChild(option);});style.value=own.style||base.style;
							const width=document.createElement('input');width.type='number';width.min='1';width.max='4';width.step='1';width.className='gh-expiry-width';width.value=own.width||base.width;
							label.append(name,color,style,width);appearance.appendChild(label);
						});updateGammaHorizonMenuCount();
					}

					function updateGammaHorizonMenuCount(){const levels=gammaHorizonData?.levels||[];const selected=levels.filter(item=>(gammaHorizonSettings.expiries[item.expiry]||{}).visible!==false).length;const count=document.getElementById('gh-menu-count');if(count)count.textContent=selected+'/'+levels.length;}
