					function readGammaHorizonSettingsInputs() {
						['D1', 'W', 'M', 'YE'].forEach(kind => {
							const visible = document.getElementById('gh-visible-' + kind);
							const color = document.getElementById('gh-color-' + kind);
							const style = document.getElementById('gh-style-' + kind);
							const width = document.getElementById('gh-width-' + kind);
							if (visible) gammaHorizonSettings[kind].visible = visible.checked;
							if (color) gammaHorizonSettings[kind].color = color.value;
							if (style) gammaHorizonSettings[kind].style = style.value;
							if (width) gammaHorizonSettings[kind].width = Math.max(1, Math.min(4, parseInt(width.value, 10) || 1));
						});
						const showLabels = document.getElementById('gh-show-labels');
						const showGreeks = document.getElementById('gh-show-greeks');
						if (showLabels) gammaHorizonSettings.showLabels = showLabels.checked;
						if (showGreeks) gammaHorizonSettings.showGreeks = showGreeks.checked;
						const recentColor=document.getElementById('gh-recent-color'),recentStyle=document.getElementById('gh-recent-style'),recentWidth=document.getElementById('gh-recent-width');
						if(recentColor)gammaHorizonSettings.recent.color=recentColor.value;if(recentStyle)gammaHorizonSettings.recent.style=recentStyle.value;if(recentWidth)gammaHorizonSettings.recent.width=Math.max(1,Math.min(4,parseInt(recentWidth.value,10)||2));
						document.querySelectorAll('#gh-expiry-appearance [data-gh-expiry]').forEach(row=>{const expiry=row.dataset.ghExpiry;const old=gammaHorizonSettings.expiries[expiry]||{};gammaHorizonSettings.expiries[expiry]=Object.assign({},old,{color:row.querySelector('.gh-expiry-color')?.value||null,style:row.querySelector('.gh-expiry-style')?.value||null,width:Math.max(1,Math.min(4,parseInt(row.querySelector('.gh-expiry-width')?.value,10)||1))});});
					}

