					}
					function readExpiryTraceSettingsInputs(){
						Object.keys(expiryTraceLines).forEach(k=>{const color=document.getElementById('et-color-'+k),style=document.getElementById('et-style-'+k),width=document.getElementById('et-width-'+k);if(color)expiryTraceLines[k].color=color.value;if(style)expiryTraceLines[k].style=style.value;if(width)expiryTraceLines[k].width=Math.max(1,Math.min(5,parseInt(width.value,10)||2));});
