					function openSettingsModal() {
						Object.keys(DEFAULT_COLORS).forEach(key => {
							const input = document.getElementById('color-' + key);
							if (input) input.value = chartColors[key];
						});
						Object.keys(DEFAULT_LINE_STYLES).forEach(key => {
							const input = document.getElementById('style-' + key);
							if (input) input.value = chartLineStyles[key];
						});
						const countInput = document.getElementById('forecast-candle-count');
						const maxCount = FORECAST_MAX_COUNTS[INTERVAL];
						if (countInput) {
							countInput.max = maxCount;
							countInput.value = forecastCandleCounts[INTERVAL];
						}
						const title = document.getElementById('forecast-settings-title');
						if (title) title.textContent = 'Forecast Candles (' + INTERVAL.toUpperCase() + ')';
						const countLabel = document.getElementById('forecast-count-label');
						if (countLabel) countLabel.textContent = 'Candle Count (1–' + maxCount + ')';
						const smoothingInput = document.getElementById('band-adaptive-smoothing');
						if (smoothingInput) smoothingInput.checked = bandAdaptiveSmoothing;
						populateGammaHorizonSettingsInputs();
						populateExpiryTraceSettingsInputs();
						populateMMHedgeSettingsInputs();
						document.getElementById('settings-modal').style.display = 'flex';
						if(!gammaHorizonData) safeRefresh('Gamma Horizon settings',()=>refreshGammaHorizon(true));
					}

					function closeSettingsModal() {
						document.getElementById('settings-modal').style.display = 'none';
					}

					function saveChartColors() {
						Object.keys(DEFAULT_COLORS).forEach(key => {
							const input = document.getElementById('color-' + key);
							if (input) chartColors[key] = input.value;
						});
						Object.keys(DEFAULT_LINE_STYLES).forEach(key => {
							const input = document.getElementById('style-' + key);
							if (input) chartLineStyles[key] = input.value;
						});
						localStorage.setItem(COLOR_STORAGE_KEY, JSON.stringify(chartColors));
						localStorage.setItem(LINE_STYLE_STORAGE_KEY, JSON.stringify(chartLineStyles));
						const smoothingInput = document.getElementById('band-adaptive-smoothing');
						if (smoothingInput) bandAdaptiveSmoothing = smoothingInput.checked;
						localStorage.setItem(BAND_SMOOTHING_STORAGE_KEY, String(bandAdaptiveSmoothing));
						const countInput = document.getElementById('forecast-candle-count');
						if (countInput) {
							const maxCount = FORECAST_MAX_COUNTS[INTERVAL];
							forecastCandleCounts[INTERVAL] = Math.max(1, Math.min(parseInt(countInput.value, 10) || maxCount, maxCount));
						}
						localStorage.setItem(FORECAST_COUNT_STORAGE_KEY, JSON.stringify(forecastCandleCounts));
						readGammaHorizonSettingsInputs();
						localStorage.setItem(GAMMA_HORIZON_SETTINGS_KEY, JSON.stringify(gammaHorizonSettings));
						readExpiryTraceSettingsInputs();
						localStorage.setItem(EXPIRY_TRACE_SETTINGS_KEY,JSON.stringify(expiryTraceLines));
						readMMHedgeSettingsInputs();
						localStorage.setItem(MM_HEDGE_SETTINGS_KEY,JSON.stringify(mmHedgeLineSettings));
						applyChartColors();
						if (SHOW_GAMMA_HORIZON) refreshGammaHorizon();
						if (SHOW_EXPIRY_PRICING) renderExpiryPricing();
						if (SHOW_MM_HEDGE) renderMMHedge();
						refreshForecast();
						closeSettingsModal();
					}

					function resetChartColors() {
						chartColors = Object.assign({}, DEFAULT_COLORS);
						chartLineStyles = Object.assign({}, DEFAULT_LINE_STYLES);
						localStorage.removeItem(COLOR_STORAGE_KEY);
						localStorage.removeItem(LINE_STYLE_STORAGE_KEY);
						localStorage.removeItem(FORECAST_COUNT_STORAGE_KEY);
						localStorage.removeItem(BAND_SMOOTHING_STORAGE_KEY);
						localStorage.removeItem(BAND_SMOOTHING_STATE_KEY);
						localStorage.removeItem(GAMMA_HORIZON_SETTINGS_KEY);
						localStorage.removeItem(EXPIRY_TRACE_SETTINGS_KEY);
						localStorage.removeItem(MM_HEDGE_SETTINGS_KEY);
						bandAdaptiveSmoothing = true;
						bandSmoothingState = {};
						forecastCandleCounts = { '1h': 72, '4h': 18, '1d': 3 };
						gammaHorizonSettings = JSON.parse(JSON.stringify(DEFAULT_GAMMA_HORIZON_SETTINGS));
						expiryTraceLines = JSON.parse(JSON.stringify(DEFAULT_EXPIRY_TRACE_LINES));
						mmHedgeLineSettings = JSON.parse(JSON.stringify(DEFAULT_MM_HEDGE_LINES));
						Object.keys(DEFAULT_COLORS).forEach(key => {
							const input = document.getElementById('color-' + key);
							if (input) input.value = chartColors[key];
						});
						Object.keys(DEFAULT_LINE_STYLES).forEach(key => {
							const input = document.getElementById('style-' + key);
							if (input) input.value = chartLineStyles[key];
						});
						const countInput = document.getElementById('forecast-candle-count');
						if (countInput) countInput.value = forecastCandleCounts[INTERVAL];
						const smoothingInput = document.getElementById('band-adaptive-smoothing');
						if (smoothingInput) smoothingInput.checked = true;
						populateGammaHorizonSettingsInputs();
						populateExpiryTraceSettingsInputs();
						populateMMHedgeSettingsInputs();
						applyChartColors();
						if (SHOW_GAMMA_HORIZON) refreshGammaHorizon();
						if (SHOW_EXPIRY_PRICING) renderExpiryPricing();
						if (SHOW_MM_HEDGE) renderMMHedge();
						refreshForecast();
					}

					let rulerActive = false;
					let rulerPrice1 = null;
					let rulerLines  = [];

					function toggleRuler() {
						rulerActive = !rulerActive;
						document.getElementById('ruler-btn').classList.toggle('active', rulerActive);
						rulerLines.forEach(l => series.removePriceLine(l));
						rulerLines = [];
						rulerPrice1 = null;
						const info = document.getElementById('ruler-info');
						info.style.display = 'none';
						info.textContent = '';
					}

					chart.subscribeCrosshairMove(param=>{
						if(!SHOW_GAMMA_HORIZON||!gammaHorizonSettings.showGreeks||pinnedGreeksHorizonKey)return;
						const items=nearbyGammaHorizonItems(param.point);showGreeksHorizonTooltip(items,param.point||{x:0,y:0},false);
					});

					chart.subscribeClick(param=>{
						if(rulerActive||!SHOW_GAMMA_HORIZON||!gammaHorizonSettings.showGreeks||!param.point)return;
						const items=nearbyGammaHorizonItems(param.point);
						if(items.length){const key=items.map(item=>item.expiry).join('|');pinnedGreeksHorizonKey=pinnedGreeksHorizonKey===key?null:key;if(pinnedGreeksHorizonKey)showGreeksHorizonTooltip(items,param.point,true);else{const tip=document.getElementById('greeks-horizon-tooltip');if(tip)tip.style.display='none';}}
						else if(pinnedGreeksHorizonKey){pinnedGreeksHorizonKey=null;const tip=document.getElementById('greeks-horizon-tooltip');if(tip)tip.style.display='none';}
					});

					chart.subscribeClick(param => {
						if (!rulerActive || !param.point) return;
						const price = series.coordinateToPrice(param.point.y);
						if (rulerPrice1 === null) {
							rulerPrice1 = price;
							rulerLines.push(series.createPriceLine({
								price, color: rulerColor(), lineWidth: 1,
								lineStyle: LightweightCharts.LineStyle.Dashed,
								axisLabelVisible: true, axisLabelColor: axisBlack(), title: '①',
							}));
						} else {
							rulerLines.push(series.createPriceLine({
								price, color: rulerColor(), lineWidth: 1,
								lineStyle: LightweightCharts.LineStyle.Dashed,
								axisLabelVisible: true, axisLabelColor: axisBlack(), title: '②',
							}));
							const pct = ((price - rulerPrice1) / rulerPrice1 * 100);
							const sign = pct >= 0 ? '+' : '';
							const info = document.getElementById('ruler-info');
							info.style.display = 'block';
							info.textContent = rulerPrice1.toFixed(0) + ' → ' + price.toFixed(0) + '   ' + sign + pct.toFixed(2) + '%';
							rulerPrice1 = null;
						}
					});

					async function safeRefresh(name, fn) {
						try { return await fn(); }
						catch (e) { console.error(name + ' refresh failed', e); setStatus(name + ': ' + e.message); return null; }
					}

					async function init() {
						await safeRefresh('Candles', loadCandles);
						// Every overlay owns its failure boundary. A low-data/failed Bands
						// request can never prevent Forecast, Zones, Gamma or Liquidity
						// from reaching the chart.
						await Promise.allSettled([
							safeRefresh('Gamma Horizon', refreshGammaHorizon),
							safeRefresh('Strategy Radar', refreshStrategyRadar),
							safeRefresh('Expiry Trace', refreshExpiryPricing),
							safeRefresh('MM Hedge', refreshMMHedge),
							safeRefresh('Bands', refreshBands),
							safeRefresh('Smart Liquidity', refreshLiveBandDots),
							safeRefresh('Zones', refreshZonesBoxes),
							safeRefresh('Nearest Expiry', refreshNearestExpiry),
							safeRefresh('Last Trade', refreshLastTrade),
							safeRefresh('Forecast', updateForecastVisibility),
							safeRefresh('Signal Bot', refreshSignalBot),
						]);
					}
					init();
					setInterval(updateLatestCandle, 5000);
					setInterval(refreshNearestExpiry, REFRESH);
					setInterval(refreshLastTrade, REFRESH);
					setInterval(() => safeRefresh('Gamma Horizon', refreshGammaHorizon), REFRESH);
					setInterval(() => safeRefresh('Strategy Radar', refreshStrategyRadar), Math.max(REFRESH, 60000));
					setInterval(() => { if(document.getElementById('expiry-trace-mode')?.value !== 'explorer') safeRefresh('Expiry Trace', refreshExpiryPricing); }, 900000);
					setInterval(() => safeRefresh('MM Hedge', refreshMMHedge), 900000);
					setInterval(() => safeRefresh('Expiry Wave', refreshExpiryWave), 900000);
					setInterval(updateExpiryPricingCountdown, 1000);
					// Bands polls on ZONES_BOX_REFRESH (not REFRESH) — its own
					// underlying dankbit.bands rows only ever change once per
					// hourly compute_snapshot() cron tick, so polling any faster
					// just re-fetches identical data; syncing it to the same
					// (slower) interval Zones already uses cuts wasted requests
					// with zero loss of real freshness, which matters more now
					// that this addon is heading toward more concurrent users.
					// refreshLiveBandDots() shares the same rationale — its own
					// dankbit.live.band rows are also hourly-cron-fed. Chained after
					// refreshBands() (rather than its own independent interval) just
					// to avoid both firing a fetch in the same tick; the two no longer
					// share any data — refreshLiveBandDots() reads only
					// dankbit.live.band, refreshBands() only dankbit.bands.
					setInterval(() => { safeRefresh('Bands', refreshBands); safeRefresh('Smart Liquidity', refreshLiveBandDots); }, ZONES_BOX_REFRESH);
					setInterval(() => safeRefresh('Zones', refreshZonesBoxes), ZONES_BOX_REFRESH);
					setInterval(() => safeRefresh('Forecast', refreshForecast), REFRESH);
					setInterval(() => safeRefresh('Signal Bot', refreshSignalBot), REFRESH);
				//

//
					// ---- Chat panel (POST /api/chat/<asset>, controllers/chat.py) ----
					// Same panel as /4l/<asset>'s and /ll/<asset>'s. Sends the nearest
					// expiry (the one the Zones boxes use) and the Option Flow window
					// (chatWindowHours()) as context plus the
					// last 2 Q/A turns for follow-ups. One request at a time —
					// answers take ~30-60 s on the local model, so an elapsed-time
					// counter shows while waiting. Answers are rendered with
					// textContent (never innerHTML).
					const chatHistory = [];
					let chatBusy = false;

					// Option Flow window as whole hours for the chat context:
					// "00:00 UTC" -> hours since UTC midnight (rounded up, min 1),
					// "Auto" -> what the server resolved for the zones boxes
					// (zonesBoxAutoHours, 24 until it's known), else the
					// selected trailing window.
					function chatWindowHours() {
						if (ZONES_BOX_WINDOW_MODE === 'midnight') {
							const now = new Date();
							const since = now.getTime() - Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate());
							return Math.max(1, Math.ceil(since / 3600000));
						}
						if (ZONES_BOX_WINDOW_MODE === 'auto') return zonesBoxAutoHours || 24;
						return selectedOptionFlowHours() || 24;
					}

					function toggleChat() {
						const panel = document.getElementById('chat-panel');
						panel.classList.toggle('open');
						if (panel.classList.contains('open')) {
							clampChatPanel();
							document.getElementById('chat-input').focus();
						}
					}

					// Draggable by its header. Once moved, the panel is
					// positioned by left/top (instead of the default right/
					// bottom corner), kept fully on screen, and the position is
					// remembered per-browser (dankbit_chart_chat_pos).
					const CHAT_POS_KEY = 'dankbit_chart_chat_pos';
					function placeChatPanel(left, top) {
						const panel = document.getElementById('chat-panel');
						const maxLeft = Math.max(0, window.innerWidth - panel.offsetWidth);
						const maxTop = Math.max(0, window.innerHeight - panel.offsetHeight);
						panel.style.left = Math.min(Math.max(0, left), maxLeft) + 'px';
						panel.style.top = Math.min(Math.max(0, top), maxTop) + 'px';
						panel.style.right = 'auto';
						panel.style.bottom = 'auto';
					}
					function clampChatPanel() {
						const panel = document.getElementById('chat-panel');
						if (panel.style.left) placeChatPanel(parseFloat(panel.style.left), parseFloat(panel.style.top));
					}
					(function initChatDrag() {
						const panel = document.getElementById('chat-panel');
						const header = document.getElementById('chat-header');
						try {
							const saved = JSON.parse(localStorage.getItem(CHAT_POS_KEY) || 'null');
							if (saved && Number.isFinite(saved.left) && Number.isFinite(saved.top)) {
								panel.style.left = saved.left + 'px';
								panel.style.top = saved.top + 'px';
								panel.style.right = 'auto';
								panel.style.bottom = 'auto';
							}
						} catch (e) { /* storage unavailable — keep default corner */ }
						let drag = null;
						header.addEventListener('pointerdown', (e) => {
							if (e.target.id === 'chat-close' || e.button !== 0) return;
							const rect = panel.getBoundingClientRect();
							drag = { dx: e.clientX - rect.left, dy: e.clientY - rect.top };
							header.setPointerCapture(e.pointerId);
							e.preventDefault();
						});
						header.addEventListener('pointermove', (e) => {
							if (drag) placeChatPanel(e.clientX - drag.dx, e.clientY - drag.dy);
						});
						const endDrag = () => {
							if (!drag) return;
							drag = null;
							try {
								localStorage.setItem(CHAT_POS_KEY, JSON.stringify({
									left: parseFloat(panel.style.left), top: parseFloat(panel.style.top),
								}));
							} catch (e) { /* ignore */ }
						};
						header.addEventListener('pointerup', endDrag);
						header.addEventListener('pointercancel', endDrag);
						window.addEventListener('resize', clampChatPanel);
					})();

					function chatAppend(cls, text) {
						const box = document.getElementById('chat-messages');
						const div = document.createElement('div');
						div.className = 'chat-msg ' + cls;
						div.dir = 'auto';
						div.textContent = text;
						box.appendChild(div);
						box.scrollTop = box.scrollHeight;
						return div;
					}

					function chatSub(parent, cls, text) {
						const d = document.createElement('div');
						d.className = cls;
						d.textContent = text;
						parent.appendChild(d);
						return d;
					}

					async function sendChat() {
						const input = document.getElementById('chat-input');
						const question = input.value.trim();
						if (!question || chatBusy) return;
						chatBusy = true;
						input.value = '';
						document.getElementById('chat-send').disabled = true;
						chatAppend('user', question);
						const status = document.getElementById('chat-status');
						const started = Date.now();
						const tick = setInterval(() => {
							status.textContent = 'Thinking… ' + Math.round((Date.now() - started) / 1000) + 's';
						}, 1000);
						status.textContent = 'Thinking… 0s';
						try {
							const resp = await fetch('/api/chat/' + ASSET, {
								method: 'POST',
								headers: { 'Content-Type': 'application/json' },
								body: JSON.stringify({
									question: question,
									page: 'chart',
									instrument: nearestExpiryStr,
									hours: chatWindowHours(),
									window_label: ZONES_BOX_WINDOW_MODE === 'midnight' ? 'since 00:00 UTC' : '',
									history: chatHistory.slice(-2),
								}),
							});
							const data = await resp.json().catch(() => ({ error: 'HTTP ' + resp.status }));
							if (!resp.ok || data.error) throw new Error(data.error || ('HTTP ' + resp.status));
							const msg = chatAppend('bot', data.answer);
							if (data.unverified_numbers && data.unverified_numbers.length) {
								chatSub(msg, 'chat-warn', '⚠ Not found in the data: ' + data.unverified_numbers.join(', ') + ' — double-check these.');
							}
							if (data.warning) {
								chatSub(msg, 'chat-warn', '⚠ ' + data.warning);
							}
							if (data.tools && data.tools.length) {
								const det = document.createElement('details');
								const sum = document.createElement('summary');
								sum.textContent = 'Data used: ' + data.tools.map(t => t.name).join(', ');
								const pre = document.createElement('pre');
								pre.textContent = JSON.stringify(data.tools, null, 1);
								det.appendChild(sum);
								det.appendChild(pre);
								msg.appendChild(det);
							}
							chatSub(msg, 'chat-meta', data.model + ' · ' + data.elapsed + 's' + (data.retried ? ' · rewritten' : ''));
							// An answer with flagged numbers never enters the follow-up history —
							// a translation request treats the previous answer as its source, so this keeps invented
							// figures from being laundered by "say that in Persian".
							if (!(data.unverified_numbers && data.unverified_numbers.length) && !data.warning) {
								chatHistory.push({ question: question, answer: data.answer });
							}
						} catch (e) {
							chatAppend('error', 'Error: ' + e.message);
						} finally {
							clearInterval(tick);
							status.textContent = '';
							chatBusy = false;
							document.getElementById('chat-send').disabled = false;
							document.getElementById('chat-messages').scrollTop = 1e9;
						}
					}

					document.getElementById('chat-input').addEventListener('keydown', (e) => {
						if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); sendChat(); }
					});
				//

//
					const fmt=(v,d=2)=>v===null||v===undefined?'—':Number(v).toFixed(d);
					function metric(label,value,cls=''){const d=document.createElement('div');d.className='card';const l=document.createElement('div');l.className='metric-label';l.textContent=label;const v=document.createElement('div');v.className='metric '+cls;v.textContent=value;d.append(l,v);return d;}
					function renderCards(s,open){const c=document.getElementById('cards');c.replaceChildren();[
						['سیگنال بسته‌شده',s.closed+'  |  باز: '+open,''],['Win Rate',s.win_rate===null?'—':fmt(s.win_rate)+'%',s.win_rate>=45?'good':s.win_rate===null?'':'warn'],
						['Profit Factor',s.profit_factor_infinite?'∞':s.profit_factor===null?'—':fmt(s.profit_factor,3),s.profit_factor_infinite||s.profit_factor>=1.4?'good':s.profit_factor===null?'':'warn'],
						['Expectancy',fmt(s.expectancy_r,3)+' R',s.expectancy_r>0?'good':s.expectancy_r<0?'bad':''],['مجموع بازده',fmt(s.total_r,2)+' R',s.total_r>0?'good':s.total_r<0?'bad':''],
						['Max Drawdown',fmt(s.max_drawdown_r,2)+' R',s.max_drawdown_r>4?'bad':''],['بیشترین باخت متوالی',s.max_loss_streak,''],
						['میانگین R:R',s.average_rr===null?'—':'1:'+fmt(s.average_rr,2),''],['برد / باخت',s.wins+' / '+s.losses,''],['Expired / Ambiguous',s.expired+' / '+s.ambiguous,'']
					].forEach(x=>c.append(metric(...x)));}
					function renderBreakdown(id,rows){const t=document.getElementById(id);t.replaceChildren();const h=document.createElement('tr');['گروه','تعداد','Win %','PF','Expectancy','Total R'].forEach(x=>{const th=document.createElement('th');th.textContent=x;h.append(th)});t.append(h);rows.forEach(r=>{const tr=document.createElement('tr');[r.name,r.closed,fmt(r.win_rate),r.profit_factor_infinite?'∞':fmt(r.profit_factor,2),fmt(r.expectancy_r,3),fmt(r.total_r,2)].forEach(x=>{const td=document.createElement('td');td.textContent=x;tr.append(td)});t.append(tr)});}
					function renderRecent(rows){const t=document.getElementById('recent');t.replaceChildren();const h=document.createElement('tr');['زمان UTC','دارایی','نوع','جهت','مدل ورود','ساختار','RTM','R:R','نتیجه','Result R'].forEach(x=>{const th=document.createElement('th');th.textContent=x;h.append(th)});t.append(h);rows.forEach(r=>{const tr=document.createElement('tr');const values=[r.time?r.time.replace('T',' ').slice(0,16):'—',r.asset,r.kind,r.direction,r.entry_model||'—',(r.rtm_structure||'—').toUpperCase(),fmt(r.rtm_score,1),fmt(r.risk_reward,2),r.state,fmt(r.result_r,2)];values.forEach((x,i)=>{const td=document.createElement('td');if(i===8){const b=document.createElement('span');b.className='badge state-'+r.state;b.textContent=String(x).toUpperCase();td.append(b)}else td.textContent=x;tr.append(td)});t.append(tr)});}
					function drawCurve(points){const canvas=document.getElementById('equity'),rect=canvas.getBoundingClientRect(),dpr=window.devicePixelRatio||1;canvas.width=Math.max(400,rect.width*dpr);canvas.height=270*dpr;const ctx=canvas.getContext('2d');ctx.scale(dpr,dpr);const w=canvas.width/dpr,h=270,pad=28;ctx.clearRect(0,0,w,h);if(!points.length){ctx.fillStyle='#667085';ctx.fillText('هنوز نتیجه بسته‌شده‌ای وجود ندارد.',pad,50);return}const vals=[0,...points.map(p=>p.equity)],min=Math.min(...vals),max=Math.max(...vals),span=Math.max(max-min,1);const x=i=>pad+i*(w-2*pad)/Math.max(points.length-1,1),y=v=>h-pad-(v-min)*(h-2*pad)/span;ctx.strokeStyle='#e4e7ec';ctx.beginPath();ctx.moveTo(pad,y(0));ctx.lineTo(w-pad,y(0));ctx.stroke();ctx.strokeStyle='#2563eb';ctx.lineWidth=2;ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(x(i),y(p.equity)):ctx.moveTo(x(i),y(p.equity)));ctx.stroke();ctx.fillStyle='#667085';ctx.fillText(max.toFixed(1)+'R',3,pad);ctx.fillText(min.toFixed(1)+'R',3,h-pad);}
					async function loadReport(){const root=document.getElementById('dashboard');root.classList.add('loading');document.getElementById('error').style.display='none';try{const q=new URLSearchParams({days:document.getElementById('days').value,asset:document.getElementById('asset').value,kind:document.getElementById('kind').value,entry_model:document.getElementById('entry_model').value});const res=await fetch('/api/signal-bot/report?'+q,{cache:'no-store'});if(!res.ok)throw new Error('HTTP '+res.status);const d=await res.json();renderCards(d.summary,d.open_count);drawCurve(d.summary.curve);renderBreakdown('by-model',d.breakdowns.entry_model);renderBreakdown('by-structure',d.breakdowns.rtm_structure);renderBreakdown('by-asset',d.breakdowns.asset);renderBreakdown('by-direction',d.breakdowns.direction);renderRecent(d.recent);document.getElementById('generated').textContent='آخرین محاسبه: '+d.generated_at.replace('T',' ').slice(0,19)+' UTC';document.getElementById('interpretation').textContent='اعتبار نمونه: '+d.sample_label+' — Win Rate فقط از TP و SL محاسبه می‌شود. Expired در Expectancy، Profit Factor، Total R و Drawdown وارد می‌شود. Ambiguous در عملکرد مالی وارد نمی‌شود. برای ارزیابی اولیه حداقل ۳۰ و برای نتیجه معنادار حداقل ۶۰ سیگنال حل‌شده لازم است.';}catch(e){const el=document.getElementById('error');el.textContent='خطا در دریافت گزارش: '+e.message;el.style.display='block';}finally{root.classList.remove('loading')}}
					window.addEventListener('resize',()=>loadReport());loadReport();setInterval(loadReport,300000);
